    let cinematicLibraryComponent;
    const cinematicLibraryActions=[];
    let cinematicUXStyles;
    let cinematicUXTimer;
    let cinematicSelectionListener;
    let cinematicGizmoThemeKey='';
    let cinematicCameraPanel;
    let cinematicKeyframeInspectorPatch;
    let cinematicKeyframeEdit = null;
    let cinematicCameraKeyframePointType;
    let cinematicFlySession=null;
    let cinematicCameraMonitor=null;
    let cinematicCameraMonitorLauncher=null;
    let cinematicCameraMonitorEnabled=true;
    let cinematicCameraMonitorSize={width:208,height:147};
    let cinematicCameraFormFinish;
    let cinematicOutlinerColors;
    let cinematicCameraPath;
    let cinematicCameraPathSignature = '';
    let cinematicCameraPathVisible = true;
    let cinematicPathPointerDown;
    let cinematicSequencerVue;
    let cinematicSequencerNode;
    let cinematicTimelineRenderPatch;
    let cinematicSequenceModeSelect;
    let cinematicSequenceAddAction;
    let cinematicWorkspaceAction;
    let cinematicRecordFrameAction;
    let cinematicSnapAction;
    let cinematicSnapEnabled = true;
    let cinematicClipClipboard = null;
    let cinematicWorkspaceSnapshot;
    let cinematicFrameWorkflow;
    let cinematicFrameWorkflowAPI;
    let cinematicWorkspaceListeners=[];
    let cinematicSequencerDrag;
    let cinematicSequencerPointerMove;
    let cinematicSequencerPointerUp;
    let cinematicSequencerBlur;
    let cinematicSequencePreview = false;
    let cinematicCameraView = null;
    let cinematicWorkspaceProject = null;
    let cinematicCompositionFrame = null;
    let cinematicCompositionPlan = null;
    let cinematicFrameEvaluationScope = null;
    let cinematicNativeStackPatch;
    let cinematicNativeTimelinePatches = [];
    let cinematicStandaloneTimelineContext;
    const managerDrafts = new Map();
    let managerDraftProject = null;
    let managerInitialSequenceId = '';
    let physicalCameraTab = 'lens';
    let montageWorkflowTab = 'shots';
    const montageClipDrafts=new Map();
    let montageCommonDraft=null;
    let montageDraftProject=null;
    let cameraLensTool;
    let cameraTransformModule;
    let cameraNativeTools=[];
    let cameraHandleDrag = null;
    let cameraHandlePointerDown;
    let cameraHandlePointerMove;
    let cameraHandlePointerUp;
    let cameraHandleWindowBlur;
    let cinematicTimelineSyncTimer = null;
    const cinematicTimelineAnimators = new Map();
    const playbackState = {
        running: false,
        ownsNativeTimeline: false,
        ownsStandaloneTransport: false,
        requestId: null,
        generation: 0,
        startClock: 0,
        startFrame: 0,
        sequenceId: ''
    };
    const publishedWindowBindings = new Map();
    const emptyProjectDocuments = new WeakMap();
    const projectDocumentCache = new WeakMap();

    function clamp(value, min, max) {
        return Math.min(max, Math.max(min, value));
    }

    function finite(value, fallback = 0) {
        const number = Number(value);
        return Number.isFinite(number) ? number : fallback;
    }

    function finiteArray(value, length, fallback) {
        if (!Array.isArray(value) || value.length < length) return fallback.slice();
        const result = value.slice(0, length).map(Number);
        return result.every(Number.isFinite) ? result : fallback.slice();
    }

    function deepClone(value) {
        return value == null ? value : JSON.parse(JSON.stringify(value));
    }

    function createId(prefix) {
        if (typeof guid === 'function') return guid();
        return prefix + '_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 9);
    }

    function cleanName(value, fallback, maxLength = 80) {
        const result = String(value == null ? '' : value).trim().slice(0, maxLength);
        return result || fallback;
    }

    function getActiveProject() {
        return typeof Project !== 'undefined' ? Project : null;
    }

    function isCinematicDesktop() {
        // Blockbench 5.x exposes isWeb; isApp is a native global, not an API property.
        return (typeof isApp !== 'undefined' && isApp === true) ||
            Blockbench.isWeb === false || Blockbench.isApp === true;
    }

    function getPreview() {
        if(cinematicFlySession)return cinematicFlySession.preview;
        if (typeof Preview !== 'undefined' && Preview.selected&&Preview.selected.id!=='lightflow_cinematic_camera_monitor') return Preview.selected;
        if (window.main_preview) return window.main_preview;
        return null;
    }

    function translate(key, fallback) {
        try {
            const translated = typeof tl === 'function' ? tl(key) : key;
            return translated && translated !== key ? translated : fallback;
        } catch (error) {
            return fallback;
        }
    }

    function hasLightflowFormType(type) {
        return Array.isArray(window.LightManagerUI?.formElementTypes) &&
            window.LightManagerUI.formElementTypes.includes(type);
    }

    function cinematicSelect(options) {
        return Object.assign({
            type: hasLightflowFormType('enum_select') ? 'enum_select' : 'select'
        }, options);
    }

    function cinematicText(options) {
        return Object.assign({
            type: hasLightflowFormType('compact_text') ? 'compact_text' : 'text'
        }, options);
    }

    function cinematicNumber(options, resetValue) {
        const step=Number(options.step);
        if(Number.isFinite(step)&&step>0&&typeof options.value==='number'){
            const digits=String(step).split('.')[1]?.length||0;
            options={...options,value:Number(options.value.toFixed(digits))};
        }
        return Object.assign({
            type: 'number',
            resettable: true,
            reset_value: resetValue
        }, options);
    }

    function cinematicVector(options, resetValue) {
        if (!hasLightflowFormType('custom_vector')) {
            return Object.assign({ type: 'vector' }, options);
        }
        return Object.assign({
            type: 'custom_vector',
            resettable: true,
            default: Array.isArray(resetValue) ? resetValue.slice() : resetValue
        }, options);
    }

    function cinematicSection(label, fallback, icon) {
        if (!hasLightflowFormType('bar_display')) {
            return { type: 'info', text: '**' + translate(label, fallback) + '**' };
        }
        return {
            type: 'bar_display',
            variant: 'subsection',
            value: translate(label, fallback),
            icon,
            paragraph: false,
            expand: true,
            color: 'var(--color-text)'
        };
    }

    function publishWindowBinding(name, value) {
        if (!publishedWindowBindings.has(name)) {
            publishedWindowBindings.set(name, {
                hadOwnValue: Object.prototype.hasOwnProperty.call(window, name),
                previousValue: window[name],
                ownedValue: value
            });
        } else {
            publishedWindowBindings.get(name).ownedValue = value;
        }
        window[name] = value;
        return value;
    }

    function restoreWindowBindings() {
        Array.from(publishedWindowBindings.entries()).reverse().forEach(([name, binding]) => {
            if (window[name] !== binding.ownedValue) return;
            if (binding.hadOwnValue) window[name] = binding.previousValue;
            else delete window[name];
        });
        publishedWindowBindings.clear();
    }

    function normalizeQuaternion(value, fallback = [0, 0, 0, 1]) {
        const result = finiteArray(value, 4, fallback);
        const length = Math.hypot(result[0], result[1], result[2], result[3]);
        if (length < 1e-10) return fallback.slice();
        return result.map(component => component / length);
    }

    function slerpQuaternion(leftValue, rightValue, amount) {
        const left = normalizeQuaternion(leftValue);
        let right = normalizeQuaternion(rightValue);
        let dot = left[0] * right[0] + left[1] * right[1] + left[2] * right[2] + left[3] * right[3];
        if (dot < 0) {
            right = right.map(component => -component);
            dot = -dot;
        }
        if (dot > 0.9995) {
            return normalizeQuaternion(left.map((component, index) => component + (right[index] - component) * amount));
        }
        const theta = Math.acos(clamp(dot, -1, 1));
        const sine = Math.sin(theta);
        if (Math.abs(sine) < 1e-8) return left.slice();
        const leftWeight = Math.sin((1 - amount) * theta) / sine;
        const rightWeight = Math.sin(amount * theta) / sine;
        return left.map((component, index) => component * leftWeight + right[index] * rightWeight);
    }

    function lerp(left, right, amount) {
        return left + (right - left) * amount;
    }

    function lerpArray(left, right, amount) {
        return left.map((value, index) => lerp(value, right[index], amount));
    }

    function easeAmount(amount, interpolation) {
        const value = clamp(amount, 0, 1);
        if (interpolation === 'step') return 0;
        if (interpolation === 'ease_in') return value * value;
        if (interpolation === 'ease_out') return 1 - (1 - value) * (1 - value);
        if (interpolation === 'smooth') return value * value * (3 - 2 * value);
        return value;
    }

    function focalLengthToVerticalFov(focalLengthMm, sensorHeightMm) {
        const focal = Math.max(0.01, finite(focalLengthMm, 50));
        const sensor = Math.max(0.01, finite(sensorHeightMm, DEFAULT_SENSOR_HEIGHT_MM));
        return 2 * Math.atan(sensor / (2 * focal)) * 180 / Math.PI;
    }

    function verticalFovToFocalLength(fovDegrees, sensorHeightMm) {
        const fov = clamp(finite(fovDegrees, 39.6), 0.01, 179) * Math.PI / 180;
        const sensor = Math.max(0.01, finite(sensorHeightMm, DEFAULT_SENSOR_HEIGHT_MM));
        return sensor / (2 * Math.tan(fov / 2));
    }

    function normalizeFrameRate(value) {
        let numerator;
        let denominator;
        if (typeof value === 'string' && value.includes('/')) {
            const parts = value.split('/').map(Number);
            numerator = parts[0];
            denominator = parts[1];
        } else if (value && typeof value === 'object') {
            numerator = Number(value.numerator);
            denominator = Number(value.denominator);
        } else {
            const numeric = Number(value);
            const matched = Object.values(FRAME_RATE_PRESETS).find(entry => Math.abs(entry.numerator / entry.denominator - numeric) < 0.0006);
            numerator = matched?.numerator || (Number.isFinite(numeric) && numeric > 0 ? numeric * 1000000 : 24);
            denominator = matched?.denominator || (Number.isFinite(numeric) && numeric > 0 ? 1000000 : 1);
        }
        numerator = Math.max(1, Math.round(finite(numerator, 24)));
        denominator = Math.max(1, Math.round(finite(denominator, 1)));
        if (Number.isSafeInteger(numerator) && Number.isSafeInteger(denominator)) {
            let a = numerator, b = denominator;
            while (b) { const remainder = a % b; a = b; b = remainder; }
            numerator /= a; denominator /= a;
        }
        return { numerator, denominator };
    }

    function frameRateKey(rate) {
        const normalized = normalizeFrameRate(rate);
        const exact = normalized.numerator + '/' + normalized.denominator;
        return exact;
    }

    function frameRateValue(rate) {
        const normalized = normalizeFrameRate(rate);
        return normalized.numerator / normalized.denominator;
    }

    function normalizeCaptureFrame(value) {
        const source = value && typeof value === 'object' ? value : {};
        const width = clamp(finite(source.width, 0.82), 0.001, 1);
        const height = clamp(finite(source.height, 0.82), 0.001, 1);
        return {
            x: clamp(finite(source.x, (1 - width) / 2), 0, 1 - width),
            y: clamp(finite(source.y, (1 - height) / 2), 0, 1 - height),
            width,
            height,
            ...(finite(source.reference_aspect,0)>0?{reference_aspect:finite(source.reference_aspect,1)}:{})
        };
    }

    function sequenceDurationFrames(sequence) {
        return Math.max(1, Math.round(finite(sequence?.end_frame, 1)) - Math.round(finite(sequence?.start_frame, 0)));
    }

    function sequenceDurationSeconds(sequence) {
        return sequenceDurationFrames(sequence) / frameRateValue(sequence?.frame_rate);
    }

    function sequenceSourceDurationSeconds(sequence) {
        return sequenceDurationSeconds(sequence) * Math.max(0.0001, finite(sequence?.playback_rate, 1));
    }

    function formatDurationSeconds(value) {
        const seconds = Math.max(0, finite(value, 0));
        const wholeMinutes = Math.floor(seconds / 60);
        const wholeSeconds = Math.floor(seconds % 60);
        const milliseconds = Math.round((seconds - Math.floor(seconds)) * 1000);
        return String(wholeMinutes).padStart(2, '0') + ':' +
            String(wholeSeconds).padStart(2, '0') + '.' +
            String(milliseconds).padStart(3, '0');
    }

    function getActiveAnimationRange() {
        const animation = typeof Animation !== 'undefined' ? Animation.selected : null;
        if (!animation) return null;
        const animationLength = Math.max(0, finite(animation.length, 0));
        const customRange = typeof Timeline !== 'undefined' && Array.isArray(Timeline.custom_range)
            ? Timeline.custom_range
            : null;
        const customStart = customRange ? Math.max(0, finite(customRange[0], 0)) : 0;
        const customEnd = customRange ? Math.max(0, finite(customRange[1], 0)) : 0;
        const usesCustomRange = customEnd > customStart + 1e-8;
        const startSeconds = usesCustomRange ? customStart : 0;
        const endSeconds = usesCustomRange ? Math.min(animationLength || customEnd, customEnd) : animationLength;
        return {
            id: String(animation.uuid || animation.name || ''),
            name: cleanName(animation.name, 'Active Animation'),
            startSeconds,
            endSeconds: Math.max(startSeconds, endSeconds),
            durationSeconds: Math.max(0, endSeconds - startSeconds)
        };
    }

    function adaptSequenceValueToActiveAnimation(sequenceValue) {
        const sequence = normalizeSequence(sequenceValue || {});
        const range = getActiveAnimationRange();
        if (!range || range.durationSeconds <= 0) return sequence;
        const frames = Math.max(1, Math.ceil(
            range.durationSeconds * frameRateValue(sequence.frame_rate) /
            Math.max(0.0001, sequence.playback_rate)
        ));
        return normalizeSequence({
            ...sequence,
            duration_mode: 'active_animation',
            source_animation_id: range.id,
            source_animation_name: range.name,
            source_start_seconds: range.startSeconds,
            end_frame: sequence.start_frame + frames
        });
    }

    function sequenceTimingSummary(sequence) {
        const frames = sequenceDurationFrames(sequence);
        const duration = sequenceDurationSeconds(sequence);
        const sourceDuration = sequenceSourceDurationSeconds(sequence);
        const firstFrame = Math.round(finite(sequence?.start_frame, 0));
        const lastFrame = firstFrame + frames - 1;
        let summary = firstFrame + '-' + lastFrame + '  |  ' +
            frames + ' ' + translate('lightflow_cinematic.unit.frames', 'frames') +
            '  |  ' + duration.toFixed(3) + ' s  |  ' + formatDurationSeconds(duration);
        if (Math.abs(sourceDuration - duration) > 1e-6) {
            summary += '  |  ' + translate('lightflow_cinematic.unit.source', 'source') +
                ' ' + sourceDuration.toFixed(3) + ' s';
        }
        if (sequence?.duration_mode === 'active_animation' && sequence.source_animation_name) {
            summary += '  |  ' + sequence.source_animation_name;
        }
        return summary;
    }

    function cinematicToolbarTimingText(sequence, frameValue) {
        if (!sequence) return 'F --/--  |  --:--.---/--:--.---';
        const firstFrame = Math.round(finite(sequence.start_frame, 0));
        const lastFrame = Math.max(firstFrame, Math.round(finite(sequence.end_frame, firstFrame + 1)) - 1);
        const frame = clamp(Math.round(finite(frameValue, firstFrame)), firstFrame, lastFrame);
        const rate = Math.max(0.0001, frameRateValue(sequence.frame_rate));
        const elapsedSeconds = (frame - firstFrame) / rate;
        return 'F ' + frame + '/' + lastFrame + '  |  ' +
            formatDurationSeconds(elapsedSeconds) + '/' + formatDurationSeconds(sequenceDurationSeconds(sequence));
    }

    function frameTimestampMicroseconds(sequence, frame) {
        const rate = normalizeFrameRate(sequence?.frame_rate);
        const start = Math.round(finite(sequence?.start_frame, 0));
        return Math.round((Math.round(frame) - start) * 1000000 * rate.denominator / rate.numerator);
    }

    function frameToTimelineSeconds(sequence, frame, subframe = false) {
        const start = Math.round(finite(sequence?.start_frame, 0));
        const sourceStart = finite(sequence?.source_start_seconds, 0);
        const playbackRate = Math.max(0.0001, finite(sequence?.playback_rate, 1));
        return sourceStart + ((subframe ? frame : Math.round(frame)) - start) * playbackRate / frameRateValue(sequence?.frame_rate);
    }

    function timelineSecondsToFrame(sequence, seconds) {
        const start = Math.round(finite(sequence?.start_frame, 0));
        const sourceStart = finite(sequence?.source_start_seconds, 0);
        const playbackRate = Math.max(0.0001, finite(sequence?.playback_rate, 1));
        return start + Math.round((finite(seconds, sourceStart) - sourceStart) * frameRateValue(sequence?.frame_rate) / playbackRate);
    }

    function defaultPhysicalCameraState() {
        return {
            projection: 'perspective',
            position: [0, 0, 32],
            quaternion: [0, 0, 0, 1],
            up: [0, 1, 0],
            target: [0, 0, 0],
            sensor_width_mm: DEFAULT_SENSOR_WIDTH_MM,
            sensor_height_mm: DEFAULT_SENSOR_HEIGHT_MM,
            focal_length_mm: 50,
            aperture_f_stop: 2.8,
            focus_distance: 32,
            shutter_angle: 180,
            iso: 100,
            exposure_compensation_ev: 0,
            lens_shift_x: 0,
            lens_shift_y: 0,
            anamorphic_squeeze: 1,
            near_clip: 0.1,
            far_clip: 1000,
            ortho_world_height: 16,
            blade_count: 7,
            layers_mask: 1
        };
    }

    function normalizePhysicalCameraState(value, fallback = defaultPhysicalCameraState()) {
        const source = value && typeof value === 'object' ? value : {};
        const base = fallback && typeof fallback === 'object' ? fallback : defaultPhysicalCameraState();
        const sensorWidth = Math.max(0.1, finite(source.sensor_width_mm, base.sensor_width_mm));
        const sensorHeight = Math.max(0.1, finite(source.sensor_height_mm, base.sensor_height_mm));
        const requestedFocalLength = source.focal_length_mm == null && source.fov != null
            ? verticalFovToFocalLength(source.fov, sensorHeight)
            : source.focal_length_mm;
        const state = {
            projection: (source.projection == null ? base.projection : source.projection) === 'orthographic'
                ? 'orthographic'
                : 'perspective',
            position: finiteArray(source.position, 3, base.position),
            quaternion: normalizeQuaternion(source.quaternion, base.quaternion),
            up: finiteArray(source.up, 3, base.up),
            target: finiteArray(source.target, 3, base.target),
            reference_aspect: Math.max(.0001, finite(source.reference_aspect, base.reference_aspect || sensorWidth / sensorHeight)),
            sensor_width_mm: sensorWidth,
            sensor_height_mm: sensorHeight,
            focal_length_mm: clamp(finite(requestedFocalLength, base.focal_length_mm), 0.1, 2000),
            aperture_f_stop: clamp(finite(source.aperture_f_stop, base.aperture_f_stop), 0.1, 128),
            focus_distance: Math.max(0.0001, finite(source.focus_distance, base.focus_distance)),
            shutter_angle: clamp(finite(source.shutter_angle, base.shutter_angle), 0, 360),
            iso: clamp(finite(source.iso, base.iso), 1, 204800),
            exposure_compensation_ev: clamp(finite(source.exposure_compensation_ev, base.exposure_compensation_ev), -20, 20),
            lens_shift_x: clamp(finite(source.lens_shift_x, base.lens_shift_x), -2, 2),
            lens_shift_y: clamp(finite(source.lens_shift_y, base.lens_shift_y), -2, 2),
            anamorphic_squeeze: clamp(finite(source.anamorphic_squeeze, base.anamorphic_squeeze), 0.25, 4),
            near_clip: Math.max(0.0001, finite(source.near_clip, base.near_clip)),
            far_clip: Math.max(0.001, finite(source.far_clip, base.far_clip)),
            ortho_world_height: Math.max(0.0001, finite(source.ortho_world_height, base.ortho_world_height)),
            blade_count: clamp(Math.round(finite(source.blade_count, base.blade_count)), 3, 32),
            layers_mask: Math.floor(finite(source.layers_mask, base.layers_mask)) >>> 0
        };
        state.far_clip = Math.max(state.near_clip + 0.001, state.far_clip);
        return state;
    }

    function interpolatePhysicalCameraState(leftValue, rightValue, amount, interpolation = 'linear') {
        const left = normalizePhysicalCameraState(leftValue);
        const right = normalizePhysicalCameraState(rightValue, left);
        const t = easeAmount(amount, interpolation);
        const numericKeys = [
            'reference_aspect', 'sensor_width_mm', 'sensor_height_mm', 'focal_length_mm', 'aperture_f_stop',
            'focus_distance', 'shutter_angle', 'iso', 'exposure_compensation_ev',
            'lens_shift_x', 'lens_shift_y', 'anamorphic_squeeze', 'near_clip',
            'far_clip', 'ortho_world_height'
        ];
        const result = {
            projection: amount >= 1 ? right.projection : left.projection,
            position: lerpArray(left.position, right.position, t),
            quaternion: slerpQuaternion(left.quaternion, right.quaternion, t),
            up: lerpArray(left.up, right.up, t),
            target: lerpArray(left.target, right.target, t),
            blade_count: Math.round(lerp(left.blade_count, right.blade_count, t)),
            layers_mask: amount >= 1 ? right.layers_mask : left.layers_mask
        };
        numericKeys.forEach(key => {
            result[key] = lerp(left[key], right[key], t);
        });
        return normalizePhysicalCameraState(result, left);
    }

    const CAMERA_KEY_CHANNELS = ['position','rotation','aim','lens','exposure'];
    function cameraKeyChannels(key) { return key.channels || CAMERA_KEY_CHANNELS; }
    function cameraChannelFields(channel) {
        if(channel==='position')return ['position'];
        if(channel==='rotation')return ['quaternion'];
        if(channel==='aim')return ['target','up','layers_mask'];
        if(channel==='exposure')return ['shutter_angle','iso','exposure_compensation_ev'];
        return ['projection','reference_aspect','sensor_width_mm','sensor_height_mm','focal_length_mm','focus_distance','aperture_f_stop','ortho_world_height','lens_shift_x','lens_shift_y','anamorphic_squeeze','blade_count','near_clip','far_clip'];
    }

    function normalizeCameraKeyframe(value, fallbackState) {
        if (!value || typeof value !== 'object') return null;
        const interpolation = ['step', 'linear', 'smooth', 'ease_in', 'ease_out'].includes(value.interpolation)
            ? value.interpolation
            : 'smooth';
        return {
            id: String(value.id || createId('cinematic_keyframe')),
            frame: Math.round(finite(value.frame, 0)),
            interpolation,
            ...(Array.isArray(value.channels)?{channels:CAMERA_KEY_CHANNELS.filter(channel=>value.channels.includes(channel))}:{}),
            state: normalizePhysicalCameraState(value.state || value, fallbackState)
        };
    }

    function normalizeCamera(value) {
        if (!value || typeof value !== 'object') return null;
        const base = normalizePhysicalCameraState(value.base || value.state);
        const keyframes = (Array.isArray(value.keyframes) ? value.keyframes : [])
            .map(entry => normalizeCameraKeyframe(entry, base))
            .filter(Boolean)
            .sort((left, right) => left.frame - right.frame);
        const unique = [];
        keyframes.forEach(entry => {
            for(let index=unique.length-1;index>=0;index--){
                const candidate=unique[index];if(candidate.frame!==entry.frame)continue;
                const remaining=cameraKeyChannels(candidate).filter(channel=>!cameraKeyChannels(entry).includes(channel));
                if(!remaining.length)unique.splice(index,1);
                else if(remaining.length!==cameraKeyChannels(candidate).length)candidate.channels=remaining;
            }
            if(cameraKeyChannels(entry).length)unique.push(entry);
        });
        return {
            id: String(value.id || createId('cinematic_camera')),
            name: cleanName(value.name, 'Camera'),
            type: 'physical',
            base,
            keyframes: unique,
            created_at: finite(value.created_at, Date.now()),
            updated_at: finite(value.updated_at, Date.now())
        };
    }

    function sanitizeStudioSettings(value) {
        const source = value && typeof value === 'object' ? value : {};
        const result = {};
        STUDIO_SETTING_KEYS.forEach(key => {
            if (Object.prototype.hasOwnProperty.call(source, key)) result[key] = deepClone(source[key]);
        });
        return result;
    }

    function captureCurrentStudioSettings() {
        return sanitizeStudioSettings(window.StudioRender?.settings || {});
    }

    function normalizeSequenceClip(value) {
        if (!value || typeof value !== 'object') return null;
        return {
            id: String(value.id || createId('sequence_clip')),
            type: value.type === 'sequence' ? 'sequence' : 'animation',
            source_id: String(value.source_id || ''),
            name: cleanName(value.name, '', 120),
            track: clamp(Math.round(finite(value.track, 0)), 0, 63),
            start_frame: Math.max(0, Math.round(finite(value.start_frame, 0))),
            duration_frames: Math.max(1, Math.round(finite(value.duration_frames, 24))),
            source_start_seconds: Math.max(0, finite(value.source_start_seconds, 0)),
            speed: clamp(finite(value.speed, 1), .01, 100),
            loop: value.loop === true,
            weight: clamp(finite(value.weight, 1), 0, 1),
            fade_in_frames: Math.max(0, Math.round(finite(value.fade_in_frames, 0))),
            fade_out_frames: Math.max(0, Math.round(finite(value.fade_out_frames, 0))),
            blend_window: value.blend_window && typeof value.blend_window === 'object' ? {
                offset_frames: Math.max(0,finite(value.blend_window.offset_frames,0)),
                duration_frames: Math.max(1,finite(value.blend_window.duration_frames,value.duration_frames||24))
            } : null,
            enabled: value.enabled !== false,
            color: clamp(Math.round(finite(value.color, -1)), -1, 9)
        };
    }

    function cinematicSlider(options, resetValue) {
        return {type:hasLightflowFormType('combo_slider')?'combo_slider':'number',
            full_track:true,slider_fill:true,resettable:true,reset_value:resetValue,
            color:'var(--color-accent)',...options};
    }

    function cinematicClipColor(index) {
        const marker=window.markerColors?.[index];
        if(!marker)return 'var(--color-accent)';
        const color=new THREE.Color(getComputedStyle(window.document.body).getPropertyValue('--color-ui').trim()||'#1e2127');
        const light=color.r*.2126+color.g*.7152+color.b*.0722>.55;
        return light?marker.standard:marker.pastel;
    }

    function cinematicClipColorItems(sequenceId,clip) {
        const labels=["light_blue","yellow","orange","red","purple","blue","green","lime","pink","silver"];
        const apply=color=>updateSequenceClips(sequenceId,selectedSequenceClips(sequenceId,clip.id).map(item=>({id:item.id,color})));
        return [{name:cinematicUI("theme_accent"),icon:'lens',marked:clip.color<0,click:()=>apply(-1)},
            '_',...(window.markerColors||[]).map((marker,index)=>({name:cinematicUI(labels[index]),icon:'lens',color:cinematicClipColor(index),marked:clip.color===index,click:()=>apply(index)}))];
    }

    function cinematicClipKeyMarkers(animation,clip,rate,playbackRate) {
        if(!animation)return [];
        const times=Array.from(new Set(Object.values(animation.animators).flatMap(animator=>animator.keyframes.map(key=>key.time)))).sort((a,b)=>a-b);
        const end=clip.source_start_seconds+clip.duration_frames/rate*clip.speed,markers=[];
        for(const key of times){
            if(clip.loop&&animation.length>0){
                if(key>=animation.length)continue;
                for(let cycle=Math.max(0,Math.ceil((clip.source_start_seconds-key)/animation.length));markers.length<256;cycle++){
                    const time=key+cycle*animation.length;if(time>=end)break;
                    markers.push((time-clip.source_start_seconds)/clip.speed*playbackRate);
                }
            }else if(key>=clip.source_start_seconds&&key<end)markers.push((key-clip.source_start_seconds)/clip.speed*playbackRate);
            if(markers.length>=256)break;
        }
        return markers.sort((a,b)=>a-b);
    }

    function normalizeSequence(value, index = 0) {
        const source = value && typeof value === 'object' ? value : {};
        const startFrame = Math.round(finite(source.start_frame, 0));
        const endFrame = Math.max(startFrame + 1, Math.round(finite(source.end_frame, startFrame + DEFAULT_SEQUENCE_LENGTH)));
        const resolution = finiteArray(source.resolution, 2, [1920, 1080])
            .map(dimension => clamp(Math.round(dimension), 1, 16384));
        const durationMode = source.clips?.length && source.duration_mode === 'active_animation' ? 'frames' : ['frames', 'seconds', 'active_animation'].includes(source.duration_mode)
            ? source.duration_mode
            : 'frames';
        return {
            id: String(source.id || createId('cinematic_sequence')),
            name: cleanName(source.name, 'Sequence ' + (index + 1)),
            frame_rate: normalizeFrameRate(source.frame_rate || { numerator: 24, denominator: 1 }),
            start_frame: startFrame,
            end_frame: endFrame,
            duration_mode: durationMode,
            source_start_seconds: Math.max(0, finite(source.source_start_seconds, 0)),
            source_animation_id: String(source.source_animation_id || ''),
            source_animation_name: cleanName(source.source_animation_name, '', 120),
            clips: (Array.isArray(source.clips) ? source.clips : []).map(normalizeSequenceClip).filter(Boolean),
            tracks: (Array.isArray(source.tracks) ? source.tracks : []).slice(0,64).map((track,index)=>({
                id:clamp(Math.round(finite(track?.id,index)),0,63),name:cleanName(track?.name,'',80),
                muted:track?.muted===true,solo:track?.solo===true,locked:track?.locked===true
            })).filter((track,index,tracks)=>tracks.findIndex(item=>item.id===track.id)===index),
            playback_rate: Math.max(0.0001, finite(source.playback_rate, 1)),
            loop_preview: source.loop_preview !== false,
            preview_camera: source.preview_camera !== false,
            resolution,
            samples: /^temporal_[124]$/.test(source.samples) ? source.samples : String(clamp(Math.round(finite(source.samples, 4)), 1, 8)),
            output_format: ['png', ...CINEMATIC_VIDEO_FORMAT_IDS, 'gif'].includes(source.output_format) ? source.output_format : 'png',
            video_codec: source.video_codec === 'auto' || CINEMATIC_VIDEO_CODEC_IDS.includes(source.video_codec)
                ? source.video_codec : 'auto',
            video_quality: CINEMATIC_QUALITY_IDS.includes(source.video_quality) ? source.video_quality : 'high',
            video_bitrate: Math.max(0, Math.round(finite(source.video_bitrate, 0))),
            video_bitrate_mode: ['variable', 'constant'].includes(source.video_bitrate_mode)
                ? source.video_bitrate_mode : 'variable',
            video_acceleration: CINEMATIC_ACCELERATION_IDS.includes(source.video_acceleration)
                ? source.video_acceleration : 'no-preference',
            keyframe_interval_seconds: clamp(finite(source.keyframe_interval_seconds, 2), 0, 60),
            export_background: source.export_background === 'transparent' ? 'transparent' : 'scene',
            audio_enabled: source.audio_enabled !== false,
            audio_codec: source.audio_codec === 'auto' || CINEMATIC_AUDIO_CODEC_IDS.includes(source.audio_codec)
                ? source.audio_codec : 'auto',
            audio_quality: CINEMATIC_QUALITY_IDS.includes(source.audio_quality) ? source.audio_quality : 'high',
            audio_bitrate: Math.max(0, Math.round(finite(source.audio_bitrate, 0))),
            audio_sample_rate: clamp(Math.round(finite(source.audio_sample_rate, 48000)), 8000, 192000),
            audio_channels: clamp(Math.round(finite(source.audio_channels, 2)), 1, 8),
            capture_area: source.capture_area === 'frame' ? 'frame' : 'full',
            render_frame: normalizeCaptureFrame(source.render_frame || source.frame),
            match_frame_ratio: source.match_frame_ratio !== false,
            camera_id: String(source.camera_id || ''),
            studio: sanitizeStudioSettings(source.studio),
            created_at: finite(source.created_at, Date.now()),
            updated_at: finite(source.updated_at, Date.now())
        };
    }

    function createDefaultSequence(index = 0) {
        const shot = captureCurrentShot('Cinematic Sequence Frame');
        const studioSettings = window.StudioRender?.settings || {};
        return normalizeSequence({
            name: 'Sequence ' + (index + 1),
            output_format: 'mp4',
            studio: captureCurrentStudioSettings(),
            capture_area: studioSettings.capture_area === 'frame' ? 'frame' : 'full',
            render_frame: shot?.frame,
            match_frame_ratio: studioSettings.match_frame_ratio !== false
        }, index);
    }

    function createEmptyDocument() {
        return {
            version: DOCUMENT_VERSION,
            active_sequence_id: '',
            active_camera_id: '',
            sequences: [],
            cameras: [],
            montage: normalizeMontage({})
        };
    }

    function normalizeDocument(value) {
        const source = value && typeof value === 'object' ? value : {};
        const sequences = (Array.isArray(source.sequences) ? source.sequences : [])
            .map(normalizeSequence)
            .filter(Boolean);
        const cameras = (Array.isArray(source.cameras) ? source.cameras : [])
            .map(normalizeCamera)
            .filter(Boolean);
        const cameraIds = new Set(cameras.map(camera => camera.id));
        sequences.forEach(sequence => {
            if (!cameraIds.has(sequence.camera_id)) sequence.camera_id = '';
        });
        const activeSequenceId = sequences.some(sequence => sequence.id === source.active_sequence_id)
            ? String(source.active_sequence_id)
            : (sequences[0]?.id || '');
        const activeSequence = sequences.find(sequence => sequence.id === activeSequenceId) || sequences[0];
        const requestedCameraId = String(source.active_camera_id || activeSequence?.camera_id || '');
        const activeCameraId = cameraIds.has(requestedCameraId) ? requestedCameraId : (activeSequence?.camera_id || '');
        return {
            version: DOCUMENT_VERSION,
            active_sequence_id: activeSequenceId,
            active_camera_id: activeCameraId,
            sequences,
            cameras,
            montage: normalizeMontage(source.montage)
        };
    }

    function normalizeMontage(value) {
        const source = value && typeof value === 'object' ? value : {};
        const output = normalizeSequence({ ...source, id: 'cinematic_montage', name: source.name || 'Montage' });
        return {
            id: 'cinematic_montage', name: output.name, frame_rate: output.frame_rate,
            resolution: output.resolution, samples: output.samples, output_format: output.output_format,
            video_codec: output.video_codec, video_quality: output.video_quality,
            video_bitrate: output.video_bitrate, video_bitrate_mode: output.video_bitrate_mode,
            video_acceleration: output.video_acceleration, keyframe_interval_seconds: output.keyframe_interval_seconds,
            export_background: output.export_background, audio_enabled: output.audio_enabled,
            audio_codec: output.audio_codec, audio_quality: output.audio_quality, audio_bitrate: output.audio_bitrate,
            audio_sample_rate: output.audio_sample_rate, audio_channels: output.audio_channels,
            clips: (Array.isArray(source.clips) ? source.clips : []).map(clip => ({
                id: String(clip.id || createId('clip')), sequence_id: String(clip.sequence_id || ''),
                in_frame: Math.round(finite(clip.in_frame, 0)), out_frame: Math.round(finite(clip.out_frame, 1)),
                speed: clamp(finite(clip.speed, 1), 0.01, 100)
            }))
        };
    }

    function updateMontage(patch, options = {}) {
        return runCinematicUndo('Edit Cinematic Montage', () => mutateDocument(document => {
            document.montage = normalizeMontage({ ...document.montage, ...patch });
            return deepClone(document.montage);
        }), options);
    }

    function addMontageClip(sequenceId, options = {}) {
        const document = readDocument();
        const sequence = document.sequences.find(item => item.id === sequenceId);
        if (!sequence) throw new Error('Montage source sequence not found.');
        const clip = { id: createId('clip'), sequence_id: sequence.id, in_frame: sequence.start_frame,
            out_frame: sequence.end_frame, speed: 1 };
        updateMontage({ clips: [...document.montage.clips, clip] }, options);
        return deepClone(clip);
    }

    function updateMontageClip(clipId, patch, options = {}) {
        const clips = readDocument().montage.clips;
        const index = clips.findIndex(clip => clip.id === clipId);
        if (index < 0) throw new Error('Montage clip not found.');
        clips[index] = { ...clips[index], ...patch, id: clips[index].id };
        return updateMontage({ clips }, options);
    }

    function moveMontageClip(clipId, offset, options = {}) {
        const clips = readDocument().montage.clips;
        const index = clips.findIndex(clip => clip.id === clipId);
        if (index < 0) throw new Error('Montage clip not found.');
        const next = clamp(index + Math.round(finite(offset, 0)), 0, clips.length - 1);
        if (index === next) return readDocument().montage;
        clips.splice(next, 0, clips.splice(index, 1)[0]);
        return updateMontage({ clips }, options);
    }

    function deleteMontageClip(clipId, options = {}) {
        return updateMontage({ clips: readDocument().montage.clips.filter(clip => clip.id !== clipId) }, options);
    }

    function buildMontagePlan(document = readDocument()) {
        const montage = normalizeMontage(document.montage);
        if (!montage.clips.length) throw new Error('Add at least one shot to the montage.');
        const outputRate = frameRateValue(montage.frame_rate);
        let exactEnd = 0, endFrame = 0;
        const shots = montage.clips.map((clip, index) => {
            const sequence = document.sequences.find(item => item.id === clip.sequence_id);
            if (!sequence) throw new Error('Montage shot ' + (index + 1) + ' references a missing sequence.');
            const camera = document.cameras.find(item => item.id === sequence.camera_id);
            if (!camera) throw new Error('Montage shot ' + (index + 1) + ' has no camera.');
            if (clip.in_frame < sequence.start_frame || clip.out_frame > sequence.end_frame || clip.out_frame <= clip.in_frame) {
                throw new Error('Invalid In/Out range for montage shot ' + (index + 1) + ': ' + sequence.name);
            }
            const start = endFrame;
            exactEnd += (clip.out_frame - clip.in_frame) / frameRateValue(sequence.frame_rate) / clip.speed * outputRate;
            endFrame = Math.round(exactEnd);
            if (endFrame <= start) throw new Error('Montage shot ' + (index + 1) + ' is shorter than one output frame.');
            return { clip, sequence, camera, start, end: endFrame };
        });
        return { shots, sequence: normalizeSequence({ ...montage, start_frame: 0, end_frame: endFrame,
            duration_mode: 'frames', camera_id: shots[0].camera.id }) };
    }

    function validateSequenceReferences(document) {
        const visit = (sequence, path) => {
            if (path.has(sequence.id)) throw new Error(cinematicUI("sequences_cannot_reference_themselves_directly_or_indirectly"));
            if (path.size >= 16) throw new Error(cinematicUI("sequence_nesting_exceeds_16_levels"));
            const next = new Set(path); next.add(sequence.id);
            for (const clip of sequence.clips || []) {
                if (clip.type !== 'sequence') continue;
                const child = document.sequences.find(item => item.id === clip.source_id);
                if (child) visit(child, next);
            }
        };
        for (const sequence of document.sequences) visit(sequence, new Set());
    }

    function addSequenceClip(sequenceId, sourceId, type = 'animation', options = {}) {
        const doc = readDocument(), sequence = getSequence(doc, sequenceId);
        const source = type === 'sequence' ? doc.sequences.find(item => item.id === sourceId)
            : getCinematicAnimations().find(item => item.uuid === sourceId);
        if (!sequence || !source) return null;
        const length = type === 'sequence' ? sequenceDurationSeconds(source) : Math.max(.001, source.length || 1);
        const clip = normalizeSequenceClip({
            source_id: sourceId, type, name: source.name,
            start_frame: options.start_frame ?? Math.max(0, currentCinematicFrame(sequence) - sequence.start_frame),
            duration_frames: Math.max(1, Math.round(length * frameRateValue(sequence.frame_rate))),
            track: options.track ?? 0, loop: type === 'animation' && source.loop === 'loop'
        });
        if(sequenceTrackState(sequence,clip.track).locked)return null;
        updateSequence(sequence.id, {clips: [...sequence.clips, clip],
            end_frame: Math.max(sequence.end_frame, sequence.start_frame + clip.start_frame + clip.duration_frames)}, options);
        return clip;
    }

    function updateSequenceClip(sequenceId, clipId, patch, options = {}) {
        const sequence = getSequence(readDocument(), sequenceId);
        if (!sequence || !sequence.clips.some(clip => clip.id === clipId)) return null;
        const clips = sequence.clips.map(clip => clip.id === clipId ? normalizeSequenceClip({...clip, ...patch, id: clip.id}) : clip);
        const last = Math.max(1,...clips.map(clip=>clip.start_frame+clip.duration_frames));
        return updateSequence(sequence.id, {clips,end_frame:Math.max(sequence.end_frame,sequence.start_frame+last)}, options);
    }

    function deleteSequenceClip(sequenceId, clipId) {
        const sequence = getSequence(readDocument(), sequenceId);
        if (sequence) updateSequence(sequence.id, {clips: sequence.clips.filter(clip => clip.id !== clipId)});
    }

    function sequenceTrackState(sequence,id) {
        return sequence?.tracks?.find(track=>track.id===id)||{id,name:'',muted:false,solo:false,locked:false};
    }

    function updateSequenceTrack(sequenceId,id,patch) {
        const sequence=getSequence(readDocumentView(),sequenceId);if(!sequence||activeRenderJob)return null;
        const tracks=sequence.tracks.filter(track=>track.id!==id);
        tracks.push({...sequenceTrackState(sequence,id),...patch,id});
        return updateSequence(sequenceId,{tracks},{undo_label:cinematicUI("edit_sequence_track")});
    }

    function updateSequenceClips(sequenceId,patches,options={}) {
        const sequence=getSequence(readDocumentView(),sequenceId);if(!sequence||activeRenderJob)return null;
        if(patches.some(patch=>{const clip=sequence.clips.find(item=>item.id===patch.id);return clip&&!sequenceTrackState(sequence,clip.track).locked&&patch.track!==undefined&&sequenceTrackState(sequence,patch.track).locked;}))return null;
        const changes=new Map(patches.map(patch=>[patch.id,patch])),clips=sequence.clips.map(clip=>{
            const patch=changes.get(clip.id);if(!patch||sequenceTrackState(sequence,clip.track).locked)return clip;
            if(patch.track!==undefined&&sequenceTrackState(sequence,patch.track).locked)return clip;
            return normalizeSequenceClip({...clip,...patch,id:clip.id});
        });
        if(JSON.stringify(clips)===JSON.stringify(sequence.clips))return null;
        return updateSequence(sequenceId,{clips,end_frame:Math.max(sequence.end_frame,sequence.start_frame+Math.max(1,...clips.map(clip=>clip.start_frame+clip.duration_frames)))},options);
    }

    function splitSequenceClips(sequenceId,ids,frame) {
        const sequence=getSequence(readDocumentView(),sequenceId);if(!sequence||activeRenderJob)return [];
        const selected=new Set(ids),created=[],relative=Math.round(frame)-sequence.start_frame,rate=frameRateValue(sequence.frame_rate);
        const clips=sequence.clips.flatMap(clip=>{
            const cut=relative-clip.start_frame;
            if(!selected.has(clip.id)||sequenceTrackState(sequence,clip.track).locked||cut<=0||cut>=clip.duration_frames)return [clip];
            const window=clip.blend_window||{offset_frames:0,duration_frames:clip.duration_frames};
            const right=normalizeSequenceClip({...clip,id:createId('sequence_clip'),start_frame:relative,duration_frames:clip.duration_frames-cut,
                source_start_seconds:clip.source_start_seconds+cut/rate*clip.speed,
                blend_window:{...window,offset_frames:window.offset_frames+cut}});
            created.push(right.id);
            return [normalizeSequenceClip({...clip,duration_frames:cut,blend_window:window}),right];
        });
        if(created.length)updateSequence(sequenceId,{clips},{undo_label:cinematicUI("split_sequence_clips")});
        return created;
    }

    function slipSequenceClips(sequenceId,ids,frames) {
        const sequence=getSequence(readDocumentView(),sequenceId);
        if(!sequence||activeRenderJob||!Number.isFinite(frames))return null;
        const clips=sequence.clips.filter(clip=>ids.includes(clip.id));
        if(!clips.length||clips.some(clip=>sequenceTrackState(sequence,clip.track).locked))return null;
        const rate=frameRateValue(sequence.frame_rate);
        // Clamp the shared displacement, not each clip: preserve relative source timing.
        const delta=Math.max(Math.round(frames),-Math.floor(Math.min(...clips.map(clip=>clip.source_start_seconds*rate/clip.speed))+1e-7));
        return updateSequenceClips(sequenceId,clips.map(clip=>({id:clip.id,
            source_start_seconds:Math.max(0,clip.source_start_seconds+delta/rate*clip.speed)
        })),{undo_label:cinematicUI("slip_selected_clips")});
    }

    function sequenceTrackGap(sequence,track,frame) {
        if(!sequence||sequenceTrackState(sequence,track).locked||!Number.isFinite(frame))return null;
        const cursor=Math.round(frame)-sequence.start_frame,clips=sequence.clips.filter(clip=>clip.track===track);
        if(cursor<0||clips.some(clip=>cursor>=clip.start_frame&&cursor<clip.start_frame+clip.duration_frames))return null;
        const before=Math.max(0,...clips.filter(clip=>clip.start_frame+clip.duration_frames<=cursor).map(clip=>clip.start_frame+clip.duration_frames));
        const after=Math.min(...clips.filter(clip=>clip.start_frame>cursor).map(clip=>clip.start_frame));
        return Number.isFinite(after)&&after>before?{start:before,end:after}:null;
    }

    function closeSequenceTrackGap(sequenceId,track,frame) {
        const sequence=getSequence(readDocumentView(),sequenceId),gap=sequenceTrackGap(sequence,track,frame);
        if(!gap||activeRenderJob)return null;
        return updateSequenceClips(sequenceId,sequence.clips.filter(clip=>clip.track===track&&clip.start_frame>=gap.end)
            .map(clip=>({id:clip.id,start_frame:clip.start_frame-(gap.end-gap.start)})),
            {undo_label:cinematicUI("close_track_gap")});
    }

    function openSequenceSlipDialog(sequenceId,ids) {
        const sequence=getSequence(readDocumentView(),sequenceId),clips=sequence?.clips.filter(clip=>ids.includes(clip.id));
        if(!clips?.length||activeRenderJob||clips.some(clip=>sequenceTrackState(sequence,clip.track).locked))return;
        const minimum=-Math.floor(Math.min(...clips.map(clip=>clip.source_start_seconds*frameRateValue(sequence.frame_rate)/clip.speed))+1e-7);
        new Dialog({id:'lightflow_cinematic_slip',title:cinematicUI("slip_source_count_clips").replace('{count}', clips.length),
            width:420,form:(window.LightManagerUI?.prepareForm || (form => form))({frames:{type:'number',label:cinematicUI("source_shift_sequence_frames"),value:0,min:minimum,step:1,
                description:cinematicUI("positive_values_use_a_later_source_segment_clip_positions_length")}}),
            onConfirm:form=>{slipSequenceClips(sequenceId,ids,Number(form.frames));cinematicSequencerVue?.sync();Animator.preview();}
        }).show();
    }

    function sequenceClipFadeWeight(clip,elapsed) {
        const position=elapsed+(clip.blend_window?.offset_frames||0),duration=clip.blend_window?.duration_frames||clip.duration_frames;
        return Math.min(clip.fade_in_frames?clamp(position/clip.fade_in_frames,0,1):1,
            clip.fade_out_frames?clamp((duration-position)/clip.fade_out_frames,0,1):1);
    }

    function cinematicClipBlendShape(clip) {
        const offset=clip.blend_window?.offset_frames||0,total=clip.blend_window?.duration_frames||clip.duration_frames;
        const samples=[0,clip.duration_frames,clip.fade_in_frames-offset,total-clip.fade_out_frames-offset];
        if(clip.fade_in_frames&&clip.fade_out_frames)samples.push(total*clip.fade_in_frames/(clip.fade_in_frames+clip.fade_out_frames)-offset);
        const points=[...new Set(samples.map(value=>clamp(value,0,clip.duration_frames)))].sort((a,b)=>a-b)
            .map(value=>(100*value/clip.duration_frames).toFixed(3)+','+(20*(1-sequenceClipFadeWeight(clip,value))).toFixed(3));
        return {line:points.join(' '),area:'0,0 '+points.join(' ')+' 100,0'};
    }

    function selectedSequenceClips(sequenceId,fallbackId) {
        const sequence=getSequence(readDocumentView(),sequenceId);if(!sequence)return [];
        const ids=new Set(cinematicSequencerVue?.sequenceId===sequenceId?cinematicSequencerVue.selectedIds:[]);
        if(fallbackId&&!ids.has(fallbackId)){ids.clear();ids.add(fallbackId);}
        return sequence.clips.filter(clip=>ids.has(clip.id));
    }

    function copySequenceClips(sequenceId,ids) {
        const sequence=getSequence(readDocumentView(),sequenceId),clips=sequence?.clips.filter(clip=>ids.includes(clip.id));
        if(!clips?.length)return false;
        cinematicClipClipboard={project:getActiveProject(),rate:frameRateValue(sequence.frame_rate),clips:deepClone(clips)};return true;
    }

    function pasteSequenceClips(sequenceId,frame,track) {
        const copied=cinematicClipClipboard,doc=readDocumentView(),sequence=getSequence(doc,sequenceId);
        if(!sequence||activeRenderJob||copied?.project!==getActiveProject())return [];
        const rate=frameRateValue(sequence.frame_rate),scale=rate/copied.rate,start=Math.min(...copied.clips.map(clip=>clip.start_frame)),firstTrack=Math.min(...copied.clips.map(clip=>clip.track));
        const baseTrack=track??firstTrack,baseFrame=Math.max(0,Math.round(frame)-sequence.start_frame);
        if(baseTrack<0||baseTrack+Math.max(...copied.clips.map(clip=>clip.track-firstTrack))>63){Blockbench.showQuickMessage(cinematicUI("not_enough_tracks_for_this_selection"));return [];}
        if(copied.clips.some(clip=>clip.type==='sequence'?!doc.sequences.some(item=>item.id===clip.source_id):!getCinematicAnimations().some(item=>item.uuid===clip.source_id))){Blockbench.showQuickMessage(cinematicUI("a_copied_source_is_missing_relink_it_before_pasting"));return [];}
        const clips=copied.clips.map(clip=>normalizeSequenceClip({...clip,id:createId('sequence_clip'),
            start_frame:baseFrame+Math.round((clip.start_frame-start)*scale),track:clip.track-firstTrack+baseTrack,
            duration_frames:Math.max(1,Math.round(clip.duration_frames*scale)),fade_in_frames:Math.round(clip.fade_in_frames*scale),fade_out_frames:Math.round(clip.fade_out_frames*scale),
            blend_window:clip.blend_window?{offset_frames:clip.blend_window.offset_frames*scale,duration_frames:clip.blend_window.duration_frames*scale}:null
        }));
        if(clips.some(clip=>sequenceTrackState(sequence,clip.track).locked))return [];
        // Validate before creating an Undo; pasting a nested sequence must not create cycles.
        const next={...sequence,clips:[...sequence.clips,...clips]};
        try{validateSequenceReferences({...doc,sequences:doc.sequences.map(item=>item.id===sequence.id?next:item)});}catch(error){Blockbench.showQuickMessage(error.message);return [];}
        updateSequence(sequenceId,{clips:next.clips,end_frame:Math.max(sequence.end_frame,sequence.start_frame+Math.max(...clips.map(clip=>clip.start_frame+clip.duration_frames)))},{undo_label:cinematicUI("paste_sequence_clips")});
        return clips.map(clip=>clip.id);
    }

    function deleteSequenceClips(sequenceId,ids) {
        const sequence=getSequence(readDocumentView(),sequenceId);if(!sequence||activeRenderJob)return;
        const clips=sequence.clips.filter(clip=>!ids.includes(clip.id)||sequenceTrackState(sequence,clip.track).locked);
        if(clips.length!==sequence.clips.length)updateSequence(sequenceId,{clips},{undo_label:cinematicUI("delete_sequence_clips")});
    }

    function snapSequenceClipDelta(sequence,clips,delta,edge,altKey) {
        if(!cinematicSnapEnabled||altKey)return {delta,target:null};
        const rate=frameRateValue(sequence.frame_rate),threshold=7/Timeline.vue.size*rate/sequence.playback_rate;
        const ids=new Set(clips.map(clip=>clip.id)),targets=[0,sequence.end_frame-sequence.start_frame,currentCinematicFrame(sequence)-sequence.start_frame];
        for(const clip of sequence.clips)if(!ids.has(clip.id))targets.push(clip.start_frame,clip.start_frame+clip.duration_frames);
        let best={delta,target:null},distance=threshold;
        for(const clip of clips){
            const anchors=edge==='left'?[clip.start_frame]:edge==='right'?[clip.start_frame+clip.duration_frames]:[clip.start_frame,clip.start_frame+clip.duration_frames];
            for(const anchor of anchors)for(const target of targets){const difference=target-anchor-delta;if(Math.abs(difference)<distance){distance=Math.abs(difference);best={delta:delta+difference,target};}}
        }
        return best;
    }

    function fitSequenceTimeline(sequenceId,selectedOnly=false) {
        const sequence=getSequence(readDocumentView(),sequenceId);if(!sequence||!Timeline.vue)return;
        const clips=selectedOnly?selectedSequenceClips(sequenceId):sequence.clips,rate=frameRateValue(sequence.frame_rate);
        const start=selectedOnly&&clips.length?Math.min(...clips.map(clip=>clip.start_frame)):0;
        const end=selectedOnly&&clips.length?Math.max(...clips.map(clip=>clip.start_frame+clip.duration_frames)):sequence.end_frame-sequence.start_frame;
        const body=window.document.getElementById('timeline_body');if(!body)return;
        const width=Math.max(80,body.clientWidth-Timeline.vue.head_width-32);
        Timeline.vue.size=clamp(width/Math.max(1/rate,(end-start)/rate*sequence.playback_rate),10,10000);
        Vue.nextTick(()=>{body.scrollLeft=Math.max(0,(sequence.source_start_seconds+start/rate*sequence.playback_rate)*Timeline.vue.size-12);});
    }

    function buildSequenceComposition(sequence, frame, document = readDocumentView(), ancestors = new Set(), inheritedWeight = 1) {
        if (!sequence || ancestors.has(sequence.id) || ancestors.size >= 16) throw new Error('Invalid recursive sequence reference');
        const path = new Set(ancestors); path.add(sequence.id);
        const plan = {animations: [], cameras: []}, rate = frameRateValue(sequence.frame_rate), relative = frame - sequence.start_frame;
        if (sequence.camera_id) {
            const camera = document.cameras.find(item => item.id === sequence.camera_id);
            if (camera) plan.cameras.push({cameraId: camera.id, state: sampleCamera(camera, frame), weight: inheritedWeight});
        }
        const clips = sequence.clips || [];
        const solo=sequence.tracks?.some(track=>track.solo),baseTrack=sequenceTrackState(sequence,0);
        if (!clips.length && sequence.source_animation_id&&!baseTrack.muted&&(!solo||baseTrack.solo)) {
            const animation = getCinematicAnimations().find(item => item.uuid === sequence.source_animation_id);
            if (!animation) throw new Error('Missing animation: ' + sequence.source_animation_name);
            plan.animations.push({animation, time: frameToTimelineSeconds(sequence, frame, true), weight: inheritedWeight, loop: animation.loop === 'loop'});
        }
        for (const clip of clips.filter(item => {const track=sequenceTrackState(sequence,item.track);return item.enabled&&!track.muted&&(!solo||track.solo);}).sort((a,b) => a.track - b.track)) {
            const elapsed = relative - clip.start_frame;
            if (elapsed < 0 || elapsed >= clip.duration_frames) continue;
            const weight = inheritedWeight * clip.weight * sequenceClipFadeWeight(clip,elapsed);
            let time = clip.source_start_seconds + elapsed / rate * clip.speed;
            if (clip.type === 'sequence') {
                const child = document.sequences.find(item => item.id === clip.source_id);
                if (!child) throw new Error('Missing sequence: ' + clip.name);
                const duration = sequenceDurationSeconds(child);
                time = clip.loop ? time % duration : Math.min(time, Math.max(0, duration - 1e-8));
                const nested = buildSequenceComposition(child, child.start_frame + time * frameRateValue(child.frame_rate), document, path, weight);
                plan.animations.push(...nested.animations); plan.cameras.push(...nested.cameras);
            } else {
                const animation = getCinematicAnimations().find(item => item.uuid === clip.source_id);
                if (!animation) throw new Error('Missing animation: ' + clip.name);
                if (animation.length > 0) time = clip.loop ? time % animation.length : Math.min(time, animation.length);
                plan.animations.push({animation, time, weight, loop: clip.loop});
            }
        }
        return plan;
    }

    function installCinematicCompositionEvaluation() {
        if (!window.Animator?.stackAnimations) return;
        const previous = Animator.stackAnimations;
        const wrapper = function(animations, inLoop, weights) {
            const context = window.LightflowCinematicFrameContext;
            const render = context?.source === 'lightflow_cinematic_render';
            const document = cinematicFrameEvaluationScope?.document || readDocumentView();
            const sequence = cinematicFrameEvaluationScope?.sequence || getSequence(document, render ? context.sequenceId : undefined);
            const frame = cinematicFrameEvaluationScope?.frame ?? (render ? context.frame : timelineSecondsToFrame(sequence, Timeline.time));
            const camera = document.cameras.find(item => item.id === sequence?.camera_id);
            if ((!render && !cinematicSequencePreview && !cinematicFrameEvaluationScope?.sequence?.clips?.length) || !sequence || (!cinematicSequencePreview&&window.AnimationController?.selected?.selected_state)) {
                cinematicCompositionPlan = null;
                return previous.apply(this, arguments);
            }
            if (camera && sequence) {
                applyCameraTimelineStateToElement(getCameraElementById(camera.id), sampleCamera(camera, frame), sequence);
            }
            const time = Timeline.time;
            const plan = buildSequenceComposition(sequence, frame, document);
            cinematicCompositionPlan = plan;
            const prepared=new Set();
            for(const entry of plan.cameras)if(!prepared.has(entry.cameraId)){
                prepared.add(entry.cameraId);
                applyCameraTimelineStateToElement(getCameraElementById(entry.cameraId),entry.state,sequence);
            }
            const parserContext = Animator.MolangParser.context.animation;
            const resetParticles = Animator.resetParticles;
            try {
                // The native evaluator provides Molang, interpolation, IK and Lightflow channels.
                // Reset effects once for the whole composition, not once per clip.
                resetParticles.call(Animator, true);
                Animator.resetParticles = () => {};
                for (const entry of plan.animations) {
                    if (entry.weight <= 0) continue;
                    Timeline.time = entry.time;
                    Animator.MolangParser.context.animation = entry.animation;
                    const loop = entry.animation.loop, override = entry.animation.override;
                    try {
                        entry.animation.loop = entry.loop ? 'loop' : 'hold';
                        if(entry.weight<1)entry.animation.override=false;
                        previous.call(this, [entry.animation], inLoop, {[entry.animation.uuid]: entry.weight});
                    } finally { entry.animation.loop = loop;entry.animation.override=override; }
                }
            } finally {
                Animator.resetParticles = resetParticles;
                Animator.MolangParser.context.animation = parserContext;
                Timeline.time = time;
            }
        };
        Animator.stackAnimations = wrapper;
        cinematicNativeStackPatch = {delete(){if(Animator.stackAnimations === wrapper)Animator.stackAnimations = previous;}};
        for (const key of ['getMaxLength','start','pause']) {
            const original = Timeline[key];
            if (typeof original !== 'function') continue;
            const next = function(...args) {
                if (!cinematicSequencePreview) return original.apply(this, args);
                const sequence = getSequence(readDocumentView());
                if (!sequence) return key === 'start' ? false : original.apply(this, args);
                if (key === 'getMaxLength') return Math.max(original.apply(this,args), sequence.source_start_seconds + sequenceSourceDurationSeconds(sequence) + 1);
                if (key === 'start') return startCinematicPlayback(sequence.id);
                const result = original.apply(this,args); pauseCinematicPlayback({pauseTimeline:false}); return result;
            };
            Timeline[key] = next;
            cinematicNativeTimelinePatches.push({delete(){if(Timeline[key] === next)Timeline[key] = original;}});
        }
    }

    function evaluatedCameraState(camera, sequence, frame) {
        let state = sampleCamera(camera, frame);
        const entries = cinematicCompositionPlan?.animations || getCinematicAnimations().filter(animation => animation.playing).map(animation => ({animation}));
        const withAnimatedPose=(cameraId,base)=>{
            const element=getCameraElementById(cameraId);let node=element,animated=false;
            while(node&&node!=='root'){
                if(entries.some(entry=>entry.weight!==0&&entry.animation.animators[node.uuid]?.keyframes?.length)){animated=true;break;}
                node=node.parent;
            }
            if(!animated||!element)return base;
            const reference=cinematicCompositionPlan?.cameras.find(entry=>entry.cameraId===cameraId)?.state||base;
            const pose=cameraElementWorldState(element,reference);
            const position=new THREE.Vector3().fromArray(base.position).add(new THREE.Vector3().fromArray(pose.position).sub(new THREE.Vector3().fromArray(reference.position)));
            const quaternion=new THREE.Quaternion().fromArray(pose.quaternion).multiply(new THREE.Quaternion().fromArray(reference.quaternion).invert()).multiply(new THREE.Quaternion().fromArray(base.quaternion));
            const target=position.clone().add(new THREE.Vector3(0,0,-Math.max(.0001,base.focus_distance)).applyQuaternion(quaternion));
            return normalizePhysicalCameraState({...base,position:position.toArray(),quaternion:quaternion.toArray(),target:target.toArray()},base);
        };
        state=withAnimatedPose(camera.id,state);
        for (const [index,entry] of (cinematicCompositionPlan?.cameras || []).entries()) {
            if (index===0 || entry.weight <= 0) continue;
            state = interpolatePhysicalCameraState(state,withAnimatedPose(entry.cameraId,entry.state),clamp(entry.weight,0,1),'linear');
        }
        return state;
    }

    function registerProjectProperty() {
        if (projectProperty || typeof Property === 'undefined') return projectProperty;
        const project = getActiveProject();
        const ProjectClass = typeof ModelProject !== 'undefined'
            ? ModelProject
            : (project?.constructor && project.constructor !== Object ? project.constructor : null);
        if (!ProjectClass) return null;
        projectProperty = new Property(ProjectClass, 'string', PROJECT_PROPERTY, {
            default: '',
            exposed: true
        });
        return projectProperty;
    }

    function hydrateProject(project, model) {
        if (!project) return;
        projectDocumentCache.delete(project);
        if (
            (!project[PROJECT_PROPERTY] || !String(project[PROJECT_PROPERTY]).trim()) &&
            typeof model?.[PROJECT_PROPERTY] === 'string'
        ) {
            project[PROJECT_PROPERTY] = model[PROJECT_PROPERTY];
        }
        if (project[PROJECT_PROPERTY] && String(project[PROJECT_PROPERTY]).trim()) {
            emptyProjectDocuments.delete(project);
        }
    }

    function readDocumentView(project = getActiveProject()) {
        if (!project) return createEmptyDocument();
        try {
            const raw = project[PROJECT_PROPERTY];
            if (!raw || !String(raw).trim()) {
                if (!emptyProjectDocuments.has(project)) {
                    emptyProjectDocuments.set(project, createEmptyDocument());
                }
                return emptyProjectDocuments.get(project);
            }
            const rawText = typeof raw === 'string' ? raw : JSON.stringify(raw);
            const cached = projectDocumentCache.get(project);
            if (cached?.raw === rawText) return cached.document;
            const document = normalizeDocument(typeof raw === 'string' ? JSON.parse(raw) : raw);
            projectDocumentCache.set(project, { raw: rawText, document });
            return document;
        } catch (error) {
            console.warn('[Lightflow Cinematic] Invalid project document; using a clean in-memory document.', error);
            if (!emptyProjectDocuments.has(project)) {
                emptyProjectDocuments.set(project, createEmptyDocument());
            }
            return emptyProjectDocuments.get(project);
        }
    }

    function readDocument(project = getActiveProject()) {
        return deepClone(readDocumentView(project));
    }

    function isPersistentProject(project = getActiveProject()) {
        if (!project) return false;
        const path = typeof project.save_path === 'string' ? project.save_path.toLowerCase() : '';
        return path.endsWith('.bbmodel') || project.format?.id === 'free' || window.Format?.id === 'free';
    }

    function writeDocument(documentValue, project = getActiveProject(), options = {}) {
        if (!project) return false;
        registerProjectProperty();
        const document = normalizeDocument(documentValue);
        validateSequenceReferences(document);
        const raw = JSON.stringify(document);
        project[PROJECT_PROPERTY] = raw;
        projectDocumentCache.set(project, { raw, document: deepClone(document) });
        emptyProjectDocuments.delete(project);
        if (typeof project.saved === 'boolean') project.saved = false;
        if (options.warn !== false && !isPersistentProject(project) && !persistenceWarningShown) {
            persistenceWarningShown = true;
            Blockbench.showQuickMessage(translate(
                'lightflow_cinematic.message.temporary',
                'Cinematic data is temporary in this format. Save as .bbmodel to keep it.'
            ), 4500);
        }
        if (options.syncElements !== false) scheduleCameraElementSync();
        scheduleCinematicTimelineSync();
        syncFpsToolbar();
        return true;
    }

    function mutateDocument(callback, options = {}) {
        const project = getActiveProject();
        if (!project) return null;
        const document = readDocument(project);
        const result = callback(document);
        writeDocument(document, project, options);
        return result;
    }

    function serializeCinematicDocumentForUndo(project = getActiveProject()) {
        return JSON.stringify(normalizeDocument(readDocumentView(project)));
    }

    function attachCinematicDocumentToCurrentUndo(project = getActiveProject()) {
        if (
            !project ||
            typeof Undo === 'undefined' ||
            !Undo.current_save
        ) return false;
        const save = Undo.current_save;
        if (!save.aspects || typeof save.aspects !== 'object') save.aspects = {};
        save.aspects[CINEMATIC_UNDO_ASPECT] = true;
        if (save[CINEMATIC_UNDO_ASPECT] === undefined) {
            save[CINEMATIC_UNDO_ASPECT] = serializeCinematicDocumentForUndo(project);
        }
        return true;
    }

    function runCinematicUndo(label, callback, options = {}) {
        const project = getActiveProject();
        if (
            options.undo === false ||
            !project ||
            typeof Undo === 'undefined' ||
            typeof Undo.initEdit !== 'function'
        ) return callback();
        if (Undo.current_save) {
            attachCinematicDocumentToCurrentUndo(project);
            return callback();
        }
        const aspects = { [CINEMATIC_UNDO_ASPECT]: true };
        Undo.initEdit(aspects);
        try {
            const result = callback();
            if (result === null || result === false) {
                Undo.cancelEdit?.(false);
            } else {
                Undo.finishEdit(label, aspects);
            }
            return result;
        } catch (error) {
            Undo.cancelEdit?.(true);
            throw error;
        }
    }

    function restoreCinematicDocumentFromUndo(serialized) {
        const project = getActiveProject();
        if (!project || serialized === undefined) return false;
        try {
            const document = normalizeDocument(
                typeof serialized === 'string' ? JSON.parse(serialized) : serialized
            );
            const raw = JSON.stringify(document);
            project[PROJECT_PROPERTY] = raw;
            projectDocumentCache.set(project, { raw, document: deepClone(document) });
            emptyProjectDocuments.delete(project);
            syncCameraElementsFromDocument();
            scheduleCinematicTimelineSync();
            syncFpsToolbar();
            scheduleManagerRefresh();
            if (cinematicFrameEditSequenceId && typeof window.StudioRender?.showFrame === 'function') {
                const sequence = getSequence(document, cinematicFrameEditSequenceId);
                if (sequence) {
                    window.StudioRender.showFrame({
                        persistProjectState: false,
                        owner: 'lightflow_cinematic',
                        settings: {
                            resolution: sequence.resolution.slice(),
                            capture_area: 'frame',
                            match_frame_ratio: sequence.match_frame_ratio
                        }
                    }, sequence.render_frame);
                }
            }
            dispatchCinematicEvent('lightflow_cinematic_document_changed', {
                cause: 'undo',
                undo: true
            });
            return true;
        } catch (error) {
            console.warn('[Lightflow Cinematic] Could not restore Cinematic undo state.', error);
            return false;
        }
    }

    function getSequence(document, id) {
        const sequenceId = String(id || document.active_sequence_id || '');
        return document.sequences.find(sequence => sequence.id === sequenceId) || document.sequences[0] || null;
    }

    function getCamera(document, id, sequence = null) {
        const cameraId = String(id || sequence?.camera_id || document.active_camera_id || '');
        return document.cameras.find(camera => camera.id === cameraId) || null;
    }

    function createSequence(value = {}, options = {}) {
        const create = () => mutateDocument(document => {
            const current = getSequence(document);
            const inheritedOutput = current ? {
                resolution: current.resolution,
                samples: current.samples,
                output_format: current.output_format,
                video_codec: current.video_codec,
                video_quality: current.video_quality,
                video_bitrate: current.video_bitrate,
                video_bitrate_mode: current.video_bitrate_mode,
                video_acceleration: current.video_acceleration,
                keyframe_interval_seconds: current.keyframe_interval_seconds,
                export_background: current.export_background,
                audio_enabled: current.audio_enabled,
                audio_codec: current.audio_codec,
                audio_quality: current.audio_quality,
                audio_bitrate: current.audio_bitrate,
                audio_sample_rate: current.audio_sample_rate,
                audio_channels: current.audio_channels
            } : { output_format: 'mp4' };
            const sequence = normalizeSequence({
                ...inheritedOutput,
                ...value,
                studio: value.studio || captureCurrentStudioSettings(),
                name: value.name || 'Sequence ' + (document.sequences.length + 1)
            }, document.sequences.length);
            document.sequences.push(sequence);
            document.active_sequence_id = sequence.id;
            document.active_camera_id = sequence.camera_id;
            return deepClone(sequence);
        });
        return runCinematicUndo(translate(
            'lightflow_cinematic.undo.create_sequence',
            'Create Cinematic Sequence'
        ), create, options);
    }

    function updateSequence(id, patch, options = {}) {
        const update = () => mutateDocument(document => {
            const index = document.sequences.findIndex(sequence => sequence.id === id);
            if (index < 0) return null;
            const previous = document.sequences[index];
            const retimed = deepClone(previous);
            if (patch?.frame_rate) retimeSequenceFrames(retimed, patch.frame_rate, document);
            const next = normalizeSequence({ ...retimed, ...(patch || {}), id: previous.id }, index);
            next.created_at = previous.created_at;
            next.updated_at = Date.now();
            document.sequences[index] = next;
            if (document.active_sequence_id === id) document.active_camera_id = next.camera_id;
            return deepClone(next);
        });
        return runCinematicUndo(options.undo_label || translate(
            'lightflow_cinematic.undo.edit_sequence',
            'Edit Cinematic Sequence'
        ), update, options);
    }

    function deleteSequence(id, options = {}) {
        const remove = () => mutateDocument(document => {
            const index = document.sequences.findIndex(sequence => sequence.id === id);
            if (index < 0) return false;
            document.sequences.splice(index, 1);
            if (document.active_sequence_id === id) {
                document.active_sequence_id = document.sequences[Math.max(0, index - 1)]?.id || '';
                document.active_camera_id = getSequence(document)?.camera_id || '';
            }
            return true;
        });
        return runCinematicUndo(translate(
            'lightflow_cinematic.undo.delete_sequence',
            'Delete Cinematic Sequence'
        ), remove, options);
    }

    function setActiveSequence(id) {
        const changed=mutateDocument(document => {
            const sequence = getSequence(document, id);
            if (!sequence) return false;
            document.active_sequence_id = sequence.id;
            document.active_camera_id = sequence.camera_id || '';
            return true;
        }, { warn: false });
        if(changed&&window.StudioRender?.frameOwner==='lightflow_cinematic'&&cinematicFrameEditSequenceId!==id&&!activeRenderJob)showCinematicRecordingFrame(id);
        return changed;
    }

    function setActiveCamera(id, options = {}) {
        const currentDocument = readDocument();
        const currentSequence = getSequence(currentDocument, options.sequence_id);
        const currentCamera = getCamera(currentDocument, id, currentSequence);
        if (
            currentSequence && currentCamera &&
            currentDocument.active_sequence_id === currentSequence.id &&
            currentDocument.active_camera_id === currentCamera.id &&
            (options.assign_to_sequence === false || currentSequence.camera_id === currentCamera.id)
        ) return true;
        return mutateDocument(document => {
            const sequence = getSequence(document, options.sequence_id);
            const camera = getCamera(document, id, sequence);
            if (!sequence || !camera) return false;
            document.active_sequence_id = sequence.id;
            document.active_camera_id = camera.id;
            if (options.assign_to_sequence !== false) sequence.camera_id = camera.id;
            return true;
        }, { warn: options.warn === true });
    }

    function deleteCamera(id, options = {}) {
        const cameraId = String(id || '');
        const remove = () => mutateDocument(document => {
            const index = document.cameras.findIndex(camera => camera.id === cameraId);
            if (index < 0) return false;
            document.cameras.splice(index, 1);
            document.sequences.forEach(sequence => {
                if (sequence.camera_id === cameraId) sequence.camera_id = '';
            });
            if (document.active_camera_id === cameraId) {
                document.active_camera_id = getSequence(document)?.camera_id || '';
            }
            return true;
        }, { syncElements: options.syncElements !== false });
        const removed = runCinematicUndo(translate(
            'lightflow_cinematic.undo.delete_camera',
            'Delete Lightflow Camera'
        ), remove, options);
        if (removed && options.syncElements !== false) syncCameraElementsFromDocument();
        return removed;
    }

    function adaptSequenceToActiveAnimation(sequenceId, options = {}) {
        const range = getActiveAnimationRange();
        if (!range || range.durationSeconds <= 0) {
            Blockbench.showQuickMessage(translate(
                'lightflow_cinematic.message.no_active_animation',
                'Select an animation with a non-zero duration first.'
            ));
            return null;
        }
        const adapt = () => mutateDocument(document => {
            const sequence = getSequence(document, sequenceId);
            if (!sequence) return null;
            const adapted = adaptSequenceValueToActiveAnimation(sequence);
            Object.assign(sequence, adapted, {
                id: sequence.id,
                created_at: sequence.created_at,
                updated_at: Date.now()
            });
            return deepClone(sequence);
        });
        return runCinematicUndo(translate(
            'lightflow_cinematic.undo.adapt_animation',
            'Fit Sequence to Active Animation'
        ), adapt, options);
    }

    function retimeSequenceFrames(sequence, rateValue, document) {
        const oldRate = frameRateValue(sequence.frame_rate), rate = normalizeFrameRate(rateValue);
        const scale = frameRateValue(rate) / oldRate;
        if (Math.abs(scale - 1) < 1e-9) return;
        sequence.start_frame = Math.round(sequence.start_frame * scale);
        sequence.end_frame = Math.max(sequence.start_frame + 1, Math.round(sequence.end_frame * scale));
        for (const clip of sequence.clips || []) {
            for (const key of ['start_frame','duration_frames','fade_in_frames','fade_out_frames']) {
                if (clip[key] != null) clip[key] = Math.max(key === 'duration_frames' ? 1 : 0, Math.round(clip[key] * scale));
            }
            if (clip.blend_window) for (const key of ['offset_frames','duration_frames']) clip.blend_window[key] *= scale;
        }
        const camera = document?.cameras.find(item => item.id === sequence.camera_id);
        if (camera) for (const key of camera.keyframes) key.frame *= scale;
        sequence.frame_rate = rate;
    }

    function setSequenceFrameRate(sequenceId, rateValue, options = {}) {
        const update = () => mutateDocument(document => {
            const sequence = getSequence(document, sequenceId);
            if (!sequence) return null;
            const previousDurationSeconds = sequenceDurationSeconds(sequence);
            retimeSequenceFrames(sequence, rateValue, document);
            if (sequence.duration_mode === 'active_animation') {
                const adapted = adaptSequenceValueToActiveAnimation(sequence);
                Object.assign(sequence, adapted, { id: sequence.id, created_at: sequence.created_at });
            } else if (sequence.duration_mode === 'seconds') {
                sequence.end_frame = sequence.start_frame + Math.max(
                    1,
                    Math.round(previousDurationSeconds * frameRateValue(sequence.frame_rate))
                );
            } else {
                sequence.end_frame = sequence.start_frame + Math.max(1, Math.round(previousDurationSeconds * frameRateValue(sequence.frame_rate)));
            }
            sequence.updated_at = Date.now();
            return deepClone(sequence);
        });
        return runCinematicUndo(translate(
            'lightflow_cinematic.undo.frame_rate',
            'Change Cinematic Frame Rate'
        ), update, options);
    }

    function getCurrentCaptureFrame(sequence) {
        if (typeof window.StudioRender?.getFrameState === 'function') {
            return normalizeCaptureFrame(window.StudioRender.getFrameState({
                owner: 'lightflow_cinematic',
                settings: {
                    resolution: sequence?.resolution || [1920, 1080],
                    capture_area: 'frame'
                }
            }));
        }
        return normalizeCaptureFrame(captureCurrentShot('Cinematic Capture Region')?.frame || sequence?.render_frame);
    }

    function projectionShiftFromCamera(camera) {
        camera?.updateProjectionMatrix?.();
        const elements = camera?.projectionMatrix?.elements || [];
        return {
            x: Number.isFinite(elements[8]) ? -elements[8] : 0,
            y: Number.isFinite(elements[9]) ? -elements[9] : 0
        };
    }

    function captureCurrentShot(name = 'Cinematic Shot') {
        if (typeof window.StudioRender?.captureShot === 'function') {
            const shot = window.StudioRender.captureShot(name, { exact_projection: true });
            if (shot) return shot;
        }
        const preview = getPreview();
        const camera = preview?.camera;
        if (!preview || !camera) return null;
        const width = Math.max(1, preview.width || preview.node?.clientWidth || 1);
        const height = Math.max(1, preview.height || preview.node?.clientHeight || 1);
        const shift = projectionShiftFromCamera(camera);
        return {
            id: createId('cinematic_shot'),
            name,
            camera: {
                projection: preview.isOrtho ? 'orthographic' : 'perspective',
                position: camera.position?.toArray?.() || [0, 0, 0],
                quaternion: camera.quaternion?.toArray?.() || [0, 0, 0, 1],
                up: camera.up?.toArray?.() || [0, 1, 0],
                target: preview.controls?.target?.toArray?.() || [0, 0, 0],
                controls_unlinked: !!preview.controls?.unlinked,
                exact_projection: true,
                near: camera.near,
                far: camera.far,
                reference_aspect: width / height,
                fov: camera.fov,
                zoom: camera.zoom,
                film_gauge: camera.filmGauge || DEFAULT_SENSOR_WIDTH_MM,
                projection_shift_x: shift.x,
                projection_shift_y: shift.y,
                focus: camera.focus,
                ortho_world_height: preview.isOrtho
                    ? (height / 40) / Math.max(0.0001, camera.zoom || 1)
                    : 1,
                layers_mask: camera.layers?.mask ?? 1
            },
            frame: { x: 0, y: 0, width: 1, height: 1 },
            output: {
                resolution_preset: 'custom',
                resolution: [width, height],
                output_scale: 1,
                capture_area: 'full',
                match_frame_ratio: true
            }
        };
    }

    function physicalStateFromShot(shot, fallback) {
        const camera = shot?.camera;
        if (!camera) return normalizePhysicalCameraState(fallback);
        const sensorWidth = Math.max(0.1, finite(camera.film_gauge, fallback?.sensor_width_mm || DEFAULT_SENSOR_WIDTH_MM));
        const aspect = Math.max(0.0001, finite(camera.reference_aspect, 16 / 9));
        const sensorHeight = Math.max(0.1, finite(fallback?.sensor_height_mm, sensorWidth / aspect));
        return normalizePhysicalCameraState({
            ...fallback,
            projection: camera.projection,
            reference_aspect: aspect,
            position: camera.position,
            quaternion: camera.quaternion,
            up: camera.up,
            target: camera.target,
            sensor_width_mm: sensorWidth,
            sensor_height_mm: sensorHeight,
            focal_length_mm: verticalFovToFocalLength(2 * Math.atan(Math.tan(camera.fov * Math.PI / 360) / Math.max(.0001, finite(camera.zoom, 1))) * 180 / Math.PI, sensorHeight),
            focus_distance: camera.focus,
            lens_shift_x: finite(camera.projection_shift_x, 0) / 2,
            lens_shift_y: finite(camera.projection_shift_y, 0) / 2,
            near_clip: camera.near,
            far_clip: camera.far,
            ortho_world_height: camera.ortho_world_height,
            layers_mask: camera.layers_mask
        }, fallback || defaultPhysicalCameraState());
    }

    function shotFromPhysicalState(stateValue, sequenceValue, name = 'Cinematic Shot') {
        const state = normalizePhysicalCameraState(stateValue);
        const sequence = normalizeSequence(sequenceValue || {});
        const aspect = sequence.capture_area === 'frame' && sequence.render_frame?.reference_aspect
            ? sequence.render_frame.reference_aspect : state.reference_aspect;
        return {
            id: createId('cinematic_shot'),
            name,
            camera: {
                projection: state.projection,
                position: state.position.slice(),
                quaternion: state.quaternion.slice(),
                up: state.up.slice(),
                target: state.target.slice(),
                controls_unlinked: true,
                exact_projection: true,
                near: state.near_clip,
                far: state.far_clip,
                reference_aspect: aspect,
                fov: focalLengthToVerticalFov(state.focal_length_mm, state.sensor_height_mm),
                zoom: 1,
                film_gauge: state.sensor_width_mm,
                lens_shift_x: 0,
                projection_shift_x: state.lens_shift_x * 2,
                projection_shift_y: state.lens_shift_y * 2,
                focus: state.focus_distance,
                ortho_world_height: state.ortho_world_height,
                layers_mask: state.layers_mask
            },
            frame: deepClone(sequence.render_frame),
            output: {
                resolution_preset: 'custom',
                resolution: sequence.resolution.slice(),
                output_scale: 1,
                capture_area: sequence.capture_area,
                match_frame_ratio: sequence.match_frame_ratio
            }
        };
    }

    function applyPhysicalStateFallback(stateValue,previewValue=null) {
        const state = normalizePhysicalCameraState(stateValue);
        const preview = previewValue || getPreview();
        if (!preview) return false;
        const isOrtho = state.projection === 'orthographic';
        if (preview.isOrtho !== isOrtho) preview.setProjectionMode?.(isOrtho);
        const camera = isOrtho ? preview.camOrtho : preview.camPers;
        if (!camera) return false;
        camera.clearViewOffset?.();
        camera.position?.fromArray?.(state.position);
        camera.quaternion?.fromArray?.(state.quaternion);
        camera.up?.fromArray?.(state.up);
        camera.near = state.near_clip;
        camera.far = state.far_clip;
        camera.focus = state.focus_distance;
        if (camera.layers) camera.layers.mask = state.layers_mask;
        const width = Math.max(1, preview.width || preview.node?.clientWidth || 1);
        const height = Math.max(1, preview.height || preview.node?.clientHeight || 1);
        if (isOrtho) {
            camera.left = -width / 80;
            camera.right = width / 80;
            camera.top = height / 80;
            camera.bottom = -height / 80;
            camera.zoom = Math.max(0.0001, (camera.top - camera.bottom) / state.ortho_world_height);
        } else {
            camera.aspect = width / height;
            camera.fov = focalLengthToVerticalFov(state.focal_length_mm, state.sensor_height_mm);
            camera.filmGauge = state.sensor_width_mm;
            camera.filmOffset = 0;
            if (typeof camera.setViewOffset === 'function' && (state.lens_shift_x || state.lens_shift_y)) {
                camera.setViewOffset(
                    width,
                    height,
                    -state.lens_shift_x * width,
                    state.lens_shift_y * height,
                    width,
                    height
                );
            }
        }
        preview.controls?.target?.fromArray?.(state.target);
        if (preview.controls) preview.controls.unlinked = true;
        camera.updateProjectionMatrix?.();
        camera.updateMatrixWorld?.(true);
        preview.render?.();
        return true;
    }

    function applyPhysicalState(state, sequence) {
        if (typeof window.StudioRender?.applyShot === 'function') {
            return window.StudioRender.applyShot(
                shotFromPhysicalState(state, sequence),
                { transient: true, notify: false }
            );
        }
        return applyPhysicalStateFallback(state);
    }

    function setArrayProperty(target, key, value) {
        if (target?.[key] && typeof target[key].replace === 'function') target[key].replace(value);
        else target[key] = value.slice();
    }

    function resolveCameraSequence(document, cameraId) {
        const active = getSequence(document);
        if (active?.camera_id === cameraId) return active;
        return document.sequences.find(sequence => sequence.camera_id === cameraId) || active;
    }

    function getCameraElementById(cameraId) {
        if (!cameraElementType) return null;
        const elements = Array.isArray(cameraElementType.all)
            ? cameraElementType.all
            : (Array.isArray(window.Outliner?.elements) ? Outliner.elements : []);
        return elements.find(element => (
            element?.type === 'lightflow_camera' &&
            (element.cinematic_camera_id === cameraId || element.uuid === cameraId)
        )) || null;
    }

    function cameraElementWorldState(element, fallbackState) {
        const fallback = normalizePhysicalCameraState(fallbackState);
        const mesh = element?.mesh;
        if (!mesh || typeof THREE === 'undefined') return fallback;
        mesh.updateMatrixWorld?.(true);
        const position = new THREE.Vector3();
        const quaternion = new THREE.Quaternion();
        mesh.getWorldPosition?.(position);
        mesh.getWorldQuaternion?.(quaternion);
        const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(quaternion);
        const target = position.clone().add(forward.multiplyScalar(Math.max(0.0001, fallback.focus_distance)));
        return normalizePhysicalCameraState({
            ...fallback,
            position: position.toArray(),
            quaternion: quaternion.toArray(),
            target: target.toArray()
        }, fallback);
    }

    function getLocalCameraTransform(element, stateValue) {
        const state = normalizePhysicalCameraState(stateValue);
        const position = new THREE.Vector3().fromArray(state.position);
        const quaternion = new THREE.Quaternion().fromArray(state.quaternion);
        if (!element?.parent?.mesh) return { position, quaternion };
        element.parent.mesh.updateMatrixWorld?.(true);
        const worldMatrix = new THREE.Matrix4().compose(position, quaternion, new THREE.Vector3(1, 1, 1));
        const parentInverse = new THREE.Matrix4().copy(element.parent.mesh.matrixWorld);
        if (typeof parentInverse.invert === 'function') parentInverse.invert();
        else if (typeof parentInverse.getInverse === 'function') parentInverse.getInverse(element.parent.mesh.matrixWorld);
        const localMatrix = parentInverse.multiply(worldMatrix);
        const localScale = new THREE.Vector3();
        localMatrix.decompose(position, quaternion, localScale);
        return { position, quaternion };
    }

    function cameraFrustumVertices(stateValue, sequence) {
        const state = normalizePhysicalCameraState(stateValue);
        const aspect = sequence?.resolution?.[0] && sequence?.resolution?.[1]
            ? sequence.resolution[0] / sequence.resolution[1]
            : state.sensor_width_mm / Math.max(0.1, state.sensor_height_mm);
        const depth = 8;
        const shifted = (vertices, halfWidth, halfHeight) => {
            for (let i = 0; i < vertices.length; i += 3) {
                if (state.projection !== 'orthographic' && vertices[i + 2] === 0) continue;
                vertices[i] -= 2 * halfWidth * state.lens_shift_x;
                vertices[i + 1] -= 2 * halfHeight * state.lens_shift_y;
            }
            return vertices;
        };
        if (state.projection === 'orthographic') {
            const halfHeight = state.ortho_world_height / 2;
            const halfWidth = halfHeight * aspect;
            return shifted([
                -halfWidth, -halfHeight, 0, -halfWidth, -halfHeight, -depth,
                 halfWidth, -halfHeight, 0,  halfWidth, -halfHeight, -depth,
                -halfWidth,  halfHeight, 0, -halfWidth,  halfHeight, -depth,
                 halfWidth,  halfHeight, 0,  halfWidth,  halfHeight, -depth,
                -halfWidth, -halfHeight, -depth,  halfWidth, -halfHeight, -depth,
                -halfWidth,  halfHeight, -depth,  halfWidth,  halfHeight, -depth,
                -halfWidth, -halfHeight, -depth, -halfWidth,  halfHeight, -depth,
                 halfWidth, -halfHeight, -depth,  halfWidth,  halfHeight, -depth
            ], halfWidth, halfHeight);
        }
        const halfHeight = Math.tan(focalLengthToVerticalFov(
            state.focal_length_mm,
            state.sensor_height_mm
        ) * Math.PI / 360) * depth;
        const halfWidth = halfHeight * aspect;
        return shifted([
            0, 0, 0, -halfWidth, -halfHeight, -depth,
            0, 0, 0,  halfWidth, -halfHeight, -depth,
            0, 0, 0, -halfWidth,  halfHeight, -depth,
            0, 0, 0,  halfWidth,  halfHeight, -depth,
            -halfWidth, -halfHeight, -depth,  halfWidth, -halfHeight, -depth,
            -halfWidth,  halfHeight, -depth,  halfWidth,  halfHeight, -depth,
            -halfWidth, -halfHeight, -depth, -halfWidth,  halfHeight, -depth,
             halfWidth, -halfHeight, -depth,  halfWidth,  halfHeight, -depth
        ], halfWidth, halfHeight);
    }

    function updateCameraElementGeometry(element, stateValue = null, sequenceValue = null) {
        if (!element?.mesh?.frustum || typeof THREE === 'undefined') return;
        const document = readDocumentView();
        const camera = getCamera(document, element.cinematic_camera_id);
        const sequence = sequenceValue || resolveCameraSequence(document, camera?.id);
        const frame = sequence
            ? clamp(timelineSecondsToFrame(sequence, typeof Timeline !== 'undefined' ? Timeline.time : 0), sequence.start_frame, sequence.end_frame - 1)
            : 0;
        const state = stateValue || sampleCamera(camera, frame) || camera?.base || defaultPhysicalCameraState();
        const vertices = cameraFrustumVertices(state, sequence);
        element.mesh.frustum.geometry.setAttribute(
            'position',
            new THREE.Float32BufferAttribute(vertices, 3)
        );
        element.mesh.frustum.geometry.computeBoundingSphere?.();
        const handles=element.mesh.cinematicHandles;
        if(handles){
            handles.focus.position.set(0,0,-Math.max(.01,state.focus_distance));
            const halfHeight=state.projection==='orthographic'?state.ortho_world_height/2:Math.tan(focalLengthToVerticalFov(state.focal_length_mm,state.sensor_height_mm)*Math.PI/360)*8;
            const aspect=sequence?.resolution?.[0]/sequence?.resolution?.[1]||state.sensor_width_mm/state.sensor_height_mm;
            handles.lens.position.set(halfHeight*aspect*(1-2*state.lens_shift_x),-2*halfHeight*state.lens_shift_y,-8);
            handles.group.visible=!!element.selected&&window.Toolbox?.selected===cameraLensTool;
        }
    }

    function applyCameraStateToElement(element, stateValue, options = {}) {
        if (!element?.mesh || typeof THREE === 'undefined') return false;
        const state = normalizePhysicalCameraState(stateValue);
        const local = getLocalCameraTransform(element, state);
        if (options.persistProperties) {
            const euler = new THREE.Euler().setFromQuaternion(
                local.quaternion,
                window.Format?.euler_order || 'ZYX'
            );
            setArrayProperty(element, 'position', local.position.toArray());
            setArrayProperty(element, 'rotation', [euler.x, euler.y, euler.z].map(value => value * 180 / Math.PI));
            cameraPreviewController?.updateTransform?.(element);
        } else {
            element.mesh.position.copy(local.position);
            element.mesh.quaternion.copy(local.quaternion);
            element.mesh.updateMatrixWorld?.(true);
            updateCameraElementGeometry(element, state, options.sequence);
        }
        return true;
    }

    function applyCameraTimelineStateToElement(element, stateValue, sequence) {
        if (!element) return false;
        if(cinematicFlySession?.cameraId===element.cinematic_camera_id)return false;
        if (Undo.current_save && pendingCameraTransformElements.has(element)) return false;
        const previousSyncState = syncingCameraElements;
        syncingCameraElements = true;
        try {
            return applyCameraStateToElement(element, stateValue, {
                persistProperties: true,
                sequence
            });
        } finally {
            syncingCameraElements = previousSyncState;
        }
    }

    function syncCameraElementTransformToDocument(target, options = {}) {
        if (!target || syncingCameraElements || target.type !== 'lightflow_camera') return null;
        if (options.attachUndo !== false) attachCinematicDocumentToCurrentUndo();
        const document = readDocument();
        const sequence = resolveCameraSequence(document, target.cinematic_camera_id);
        const camera = getCamera(document, target.cinematic_camera_id, sequence);
        if (!sequence || !camera) return null;
        const frame = clamp(
            timelineSecondsToFrame(sequence, typeof Timeline !== 'undefined' ? Timeline.time : 0),
            sequence.start_frame,
            sequence.end_frame - 1
        );
        const previous = sampleCamera(camera, frame) || camera.base;
        const state=cameraElementWorldState(target,previous),channels=changedCameraPoseChannels(previous,state);
        if(!channels.length)return null;
        return channels.map(channel=>addOrUpdateCameraKeyframe(camera.id, frame, {
            sequence_id: sequence.id,
            state,channel,
            interpolation: camera.keyframes.find(keyframe => keyframe.frame === frame)?.interpolation || 'smooth',
            camera_name: target.name,
            syncElements: false,
            undo: false
        }));
    }

    function queueCameraElementTransformWrite(element) {
        // Preview refreshes, Undo restores and frame evaluation also call this
        // controller. Only an authored element edit may persist its transform.
        if (syncingCameraElements || cinematicFrameEvaluationScope || activeRenderJob || !element) return;
        if (!Undo.current_save?.aspects?.elements?.includes(element)) return;
        pendingCameraTransformElements.add(element);
        attachCinematicDocumentToCurrentUndo();
    }

    function registerCinematicUndoHooks() {
        if (cinematicUndoHooks || typeof Blockbench === 'undefined') return cinematicUndoHooks;
        const createSaveListener = Blockbench.on('create_undo_save', event => {
            const markers = (event?.aspects?.keyframes || []).filter(marker=>marker?.animator?.type==='lightflow_camera_timeline');
            if (markers.length && event.save) {
                event.aspects[CINEMATIC_UNDO_ASPECT] = true;
                // Document mirrors must not become bone animators during Undo.
                for (const marker of markers) if(event.save.keyframes) delete event.save.keyframes[marker.uuid];
                if (event.save.keyframes && Object.keys(event.save.keyframes).every(key=>key==='animation')) delete event.save.keyframes;
            }
            if (!event?.aspects?.[CINEMATIC_UNDO_ASPECT] || !event.save) return;
            event.save[CINEMATIC_UNDO_ASPECT] = serializeCinematicDocumentForUndo();
        });
        const finishEditListener = Blockbench.on('finish_edit', event => {
            if (unloading || syncingCameraElements) return;
            const affected = new Set(pendingCameraTransformElements);
            pendingCameraTransformElements.clear();
            affected.forEach(element => syncCameraElementTransformToDocument(element));
            const renamed = (event?.aspects?.elements || []).filter(element => element?.type === 'lightflow_camera');
            if (renamed.some(element => getCamera(readDocumentView(),element.cinematic_camera_id)?.name !== element.name)) {
                attachCinematicDocumentToCurrentUndo();
                mutateDocument(document => {
                    renamed.forEach(element => {
                        const camera=getCamera(document,element.cinematic_camera_id);
                        if(camera)camera.name=cleanName(element.name,camera.name);
                    });
                }, {syncElements:false});
            }
            syncCinematicTimelineKeyframesToDocument(event?.aspects?.keyframes);
            if (typeof Undo !== 'undefined' && Undo.current_save?.aspects?.[CINEMATIC_UNDO_ASPECT]) {
                event.aspects[CINEMATIC_UNDO_ASPECT] = true;
            }
        });
        const loadSaveListener = Blockbench.on('load_undo_save', event => {
            pendingCameraTransformElements.clear();
            const serialized = event?.save?.[CINEMATIC_UNDO_ASPECT];
            if (serialized === undefined) return;
            restoreCinematicDocumentFromUndo(serialized);
        });
        cinematicUndoHooks = {
            delete() {
                createSaveListener?.delete?.();
                finishEditListener?.delete?.();
                loadSaveListener?.delete?.();
                cinematicUndoHooks = null;
            }
        };
        return cinematicUndoHooks;
    }

    function syncCameraGizmoVisibility() {
        if (!cameraElementType) return;
        const showGizmos = typeof Canvas === 'undefined' || Canvas.show_gizmos !== false;
        const theme=window.CustomTheme?.data?.colors||{};
        const back=new THREE.Color(theme.back||'#181b1f');
        const light=back.r*.2126+back.g*.7152+back.b*.0722>.55;
        const css=getComputedStyle(window.document.body);
        const idle=css.getPropertyValue('--lf-cinematic-camera').trim()||(light?'#8D3854':'#E8A8B5'),focus=light?0x167f6a:0x87d9c2,lens=light?0x9b670d:0xe9c47a;
        (cameraElementType.all || []).forEach(element => {
            if (element.mesh) {
                const color=element.selected?(css.getPropertyValue('--lf-cinematic-camera-selected').trim()||idle):idle;
                element.mesh.material?.color?.set(color);
                element.mesh.frustum?.material?.color?.set(color);
                element.mesh.cinematicDirection?.material?.color?.set(idle);
                element.mesh.visible = element.visibility !== false && showGizmos;
                if(element.mesh.frustum)element.mesh.frustum.visible=!!element.selected;
                const handles=element.mesh.cinematicHandles;
                if(handles){
                    handles.group.visible=!!element.selected&&window.Toolbox?.selected===cameraLensTool;
                    handles.focus.material.color.setHex(focus);
                    handles.focus.children.forEach(child=>child.material?.color?.setHex(focus));
                    handles.lens.material.color.setHex(lens);
                }
            }
        });
    }

    function installCinematicCameraWorkspace() {
        if (!window.document?.createElement || typeof Panel === 'undefined' || typeof THREE === 'undefined') return;
        const style = window.document.createElement('style'); window.document.head.appendChild(style);
        let signature = '';
        const contrastInk = background => {
            const color = new THREE.Color(background || '#202226');
            const lum = value => [value.r,value.g,value.b].map(channel => channel <= .04045 ? channel/12.92 : ((channel+.055)/1.055)**2.4)
                .reduce((sum,value,index)=>sum+value*[.2126,.7152,.0722][index],0);
            const base = new THREE.Color(lum(color) > .35 ? '#8D3854' : '#E8A8B5');
            const target = new THREE.Color(lum(color) > .179 ? '#000000' : '#ffffff');
            for (let amount=0;amount<=1;amount+=.01) {
                const ink=base.clone().lerp(target,amount),a=lum(ink),b=lum(color);
                if ((Math.max(a,b)+.05)/(Math.min(a,b)+.05)>=4.5) return '#'+ink.getHexString();
            }
            return '#'+target.getHexString();
        };
        const sync = () => {
            const css=getComputedStyle(window.document.body),back=css.getPropertyValue('--color-ui').trim(),selected=css.getPropertyValue('--color-selected').trim();
            if(signature===back+'|'+selected)return;signature=back+'|'+selected;
            style.textContent=`:root{--lf-cinematic-camera:${contrastInk(back)};--lf-cinematic-camera-selected:${contrastInk(selected)};--lf-cinematic-record:${new THREE.Color(back||'#1e2127').r>.55?'#b62d43':'#ff8999'};}
                #panel_outliner .lightflow-cinematic-camera > :is(.cube_name,.icon,.dynamic-icon){color:var(--lf-cinematic-camera)!important;}
                #panel_outliner .lightflow-cinematic-camera.selected > :is(.cube_name,.icon,.dynamic-icon){color:var(--lf-cinematic-camera-selected)!important;}
                .lf-camera-panel{padding:6px 8px;display:flex;flex-direction:column;gap:5px;}
                .lf-camera-actions{display:flex;flex-wrap:wrap;gap:3px;align-items:center;justify-content:space-between;border-top:1px solid var(--color-border);padding-top:5px;}.lf-camera-panel>*{min-width:0;}.lf-camera-panel button{background:transparent;box-shadow:none;border:0;border-radius:8px;padding:3px;min-width:28px;height:28px;}
                .lf-camera-footer{display:none;}
                #panel_lightflow_cinematic_camera .lf-camera-name-row{display:flex!important;align-items:center;gap:6px;}
                #panel_lightflow_cinematic_camera .lf-camera-name-row>.bar_display{flex:1;min-width:0;}
                #panel_lightflow_cinematic_camera .lf-camera-name-row>.lf-camera-settings{display:grid;place-items:center;flex:0 0 28px;width:28px;min-width:28px;height:28px;padding:4px;border:0;border-radius:8px;background:var(--color-button);color:var(--color-text);}
                #panel_lightflow_cinematic_camera .lf-camera-name-row>.lf-camera-settings>span{display:none;}
                #panel_lightflow_cinematic_camera .lf-camera-name-row>.lf-camera-settings>.material-icons{font-size:18px;line-height:18px;}
                #panel_lightflow_cinematic_camera>.form .dialog_bar{margin-block:4px;}
                #panel_lightflow_cinematic_camera>.form .form_bar:not(.form_bar_camera_name){display:none!important;}
                #panel_lightflow_cinematic_camera .lf-camera-panel{display:none;}
                .lf-camera-primary{display:flex;gap:6px;}.lf-camera-primary button{flex:1;min-width:0;height:auto;min-height:30px;white-space:normal;line-height:1.2;display:flex;gap:5px;align-items:center;justify-content:center;background:var(--color-button);}
                .lf-camera-actions .lf-camera-divider{height:15px;border-left:1px solid var(--color-border);margin:0 3px;}.lf-camera-actions .lf-camera-settings{margin-left:auto;}
                .lf-camera-section-label{font-size:11px;color:var(--color-subtle_text);margin:3px 0 0;}
                .lf-camera-movement{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px;}
                .lf-camera-movement button{display:flex;align-items:center;justify-content:center;gap:4px;min-width:0;height:auto;min-height:30px;white-space:normal;line-height:1.2;}
                .lf-camera-primary button.active{background:var(--color-selected);color:var(--lf-cinematic-camera);}
                .lf-camera-panel .lf-camera-record{display:flex;align-items:center;justify-content:center;gap:6px;min-height:32px;height:auto;background:var(--color-button);color:var(--lf-cinematic-record);white-space:normal;}
                #panel_lightflow_cinematic_camera>.form{padding:6px 8px 0;}
                .lf-camera-primary .record{color:var(--lf-cinematic-record);}
                .lf-camera-panel button:hover{background:var(--color-button);}.lf-camera-panel button.active{color:var(--lf-cinematic-camera);}
                .lf-camera-panel :is(button,input):focus-visible{outline:2px solid var(--color-accent);outline-offset:-2px;}
                .lf-camera-panel button .material-icons{font-size:19px;}
                #panel_lightflow_cinematic_camera .lf-camera-panel{padding:6px 8px!important;}`;
        };
        const listener=Blockbench.on('get_outliner_node_classes',({node,classes})=>{if(node.type==='lightflow_camera')classes.push('lightflow-cinematic-camera');});
        cinematicOutlinerColors={sync,delete(){listener.delete();style.remove();}};sync();
        let cameraEdit=null;
        const beginCameraEdit=()=>{
            if(cameraEdit||activeRenderJob)return;
            const element=(getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement()),doc=readDocumentView(),sequence=resolveCameraSequence(doc,element?.cinematic_camera_id);
            if(!element||!sequence)return;
            pauseCinematicPlayback();
            cameraEdit={cameraId:element.cinematic_camera_id,sequenceId:sequence.id,frame:currentCinematicFrame(sequence),before:JSON.stringify(doc)};
            Undo.initEdit({[CINEMATIC_UNDO_ASPECT]:true});
        };
        cinematicCameraFormFinish=cancel=>{
            if(!cameraEdit)return;
            const changed=cameraEdit.before!==JSON.stringify(readDocumentView());cameraEdit=null;
            if(cancel||!changed)Undo.cancelEdit(true);else Undo.finishEdit(cinematicUI("edit_camera_lens"),{[CINEMATIC_UNDO_ASPECT]:true});
        };
        const orthographic=()=>{
            const element=(getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement()),doc=readDocumentView(),sequence=resolveCameraSequence(doc,element?.cinematic_camera_id),camera=doc.cameras.find(item=>item.id===element?.cinematic_camera_id);
            return camera&&sequence&&sampleCamera(camera,currentCinematicFrame(sequence)).projection==='orthographic';
        };
        const cameraField=(options,reset)=>cinematicSlider({...options,onBefore:beginCameraEdit,onAfter:()=>cinematicCameraFormFinish(false),onCancel:()=>cinematicCameraFormFinish(true),compact:false,full_track:true,color:'var(--lf-cinematic-camera)'},reset);
        cinematicCameraPanel = new Panel('lightflow_cinematic_camera',{
            name:cinematicUI("camera"),icon:'videocam',growable:false,resizable:false,
            insert_before:'outliner',
            condition:()=>!!getSelectedCameraElement()&&['edit','animate','render'].includes(Project?.mode),
            default_position:{slot:'right_bar',height:88,sidebar_index:1,folded:false},
            form:(window.LightManagerUI?.prepareForm || (form => form))({
                camera_name:hasLightflowFormType('bar_display')?{type:'bar_display',value:'',icon:'videocam',expand:true,color:'var(--lf-cinematic-camera)'}:{type:'info',text:''},
                focal_length_mm:cameraField({label:cinematicUI("lens_mm"),icon:'camera',value:50,min:8,max:200,allow_higher:true,step:.1,condition:()=>!orthographic()},50),
                ortho_world_height:cameraField({label:cinematicUI("frame_height"),icon:'height',value:16,min:.001,max:64,allow_higher:true,step:.1,condition:orthographic},16),
                focus_distance:cameraField({label:cinematicUI("focus_guide"),description:cinematicUI("guide_distance_in_scene_units_does_not_add_depth_of_field_blur"),icon:'center_focus_weak',value:10,min:.001,max:100,allow_higher:true,step:.1},10)
            }),
            component:{
                data(){return {name:'',lens:50,focus:10,ortho:false,path:true,frame:false,busy:false,keyCount:0,animating:false,looking:false,monitorVisible:true};},
                methods:{
                    sync(){
                        if(cameraEdit||cinematicCameraPanel?.form?.node?.contains(window.document.activeElement))return;
                        const element=(getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement()),doc=readDocumentView(),seq=resolveCameraSequence(doc,element?.cinematic_camera_id),camera=doc.cameras.find(item=>item.id===element?.cinematic_camera_id);
                        if(!camera||!seq)return;const state=sampleCamera(camera,currentCinematicFrame(seq));
                        this.animating=Project.mode==='animate';this.name=camera.name;this.ortho=state.projection==='orthographic';this.lens=this.ortho?state.ortho_world_height:state.focal_length_mm;this.focus=state.focus_distance;this.path=cinematicCameraPathVisible;this.busy=!!activeRenderJob;this.keyCount=camera.keyframes.length;
                        this.frame=window.StudioRender?.frameOwner==='lightflow_cinematic';this.looking=cinematicCameraView?.cameraId===camera.id;this.monitorVisible=cinematicCameraMonitorEnabled;
                        const form=cinematicCameraPanel?.form;
                        if(form){
                            form.node.inert=this.busy;
                            // combo_slider dispatches input by default. Hydrating a panel must
                            // neither create camera keys nor consume an Undo during playback.
                            for(const [key,value] of Object.entries({camera_name:camera.name,focal_length_mm:Number(state.focal_length_mm.toFixed(2)),ortho_world_height:Number(state.ortho_world_height.toFixed(2)),focus_distance:Number(state.focus_distance.toFixed(2))}))form.form_data[key]?.setValue?.(value,false);
                            form.updateValues({cause:'update_value'});
                        }
                    },
                    settings(){if(!activeRenderJob)openPhysicalCameraDialog((getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement())?.cinematic_camera_id);},
                    view(){if(!activeRenderJob)viewThroughCameraAction?.trigger();},
                    capture(){if(!activeRenderJob)updateCameraFromViewAction?.trigger();},
                    recordFrame(){if(!activeRenderJob)cinematicRecordFrameAction?.trigger();},
                    record(){const el=(getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement()),seq=resolveCameraSequence(readDocumentView(),el?.cinematic_camera_id);if(seq&&!activeRenderJob)renderConfiguredSequence(seq.id).then(reportRenderResult).catch(showCinematicError);},
                    more(event){new Menu([{name:cinematicUI("camera_settings"),icon:'tune',click:()=>this.settings()},{name:cinematicUI("animate_in_blockbench"),icon:'movie',click:()=>this.animate()},{name:cinematicUI("recording_frame"),icon:'crop_free',click:()=>this.recordFrame()}]).open(event);},
                    key(){
                        if(activeRenderJob)return;const el=(getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement());if(!el)return;
                        keyCameraPose(el.cinematic_camera_id,resolveCameraSequence(readDocumentView(),el.cinematic_camera_id)?.id);
                    },
                    keys(){if(activeRenderJob)return;const el=(getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement());Modes.options.animate.select();if(el&&Animation.selected&&!cinematicSequencePreview)Animation.selected.getBoneAnimator(el).select();else showActiveCameraTimelineTrack({select:true});},
                    trail(){toggleCinematicCameraPath();this.path=cinematicCameraPathVisible;},
                    fly(){startCinematicFly();},
                    monitor(){toggleCinematicCameraMonitor();},
                    animate(){
                        if(activeRenderJob)return;setCinematicSequencePreview(false);
                        if(!Animation.selected){const camera=(getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement());const animation=new Animation({name:(camera?.name||'Camera')+' · '+cinematicUI("motion"),length:sequenceDurationSeconds(getSequence(readDocumentView()))});Undo.initEdit({animations:[animation]});animation.add();Undo.finishEdit('Create camera animation');animation.select();}
                        Modes.options.animate.select();const el=(getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement())||getCameraElementById(readDocumentView().active_camera_id);el?.select();
                    }
                },
                template:`<div class="lf-camera-panel">
                    <div class="lf-camera-footer">
                        <button :disabled="busy" class="lf-camera-settings" @click="settings" title="${cinematicUI("camera_settings")}" aria-label="${cinematicUI("camera_settings")}"><i class="material-icons" aria-hidden="true">tune</i><span>${cinematicUI("camera_settings")}</span></button>
                    </div>
                </div>`
            }
        });
        cinematicCameraPanel.form.on('input',({result,changed_keys})=>{
            if(activeRenderJob)return;
            const doc=readDocumentView(),cameraId=cameraEdit?.cameraId||(getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement())?.cinematic_camera_id;
            const camera=doc.cameras.find(item=>item.id===cameraId),sequence=resolveCameraSequence(doc,cameraId);
            if(!camera||!sequence)return;
            const frame=cameraEdit?.frame??currentCinematicFrame(sequence),state=sampleCamera(camera,frame);
            const changed=(changed_keys||[]).filter(key=>['focal_length_mm','ortho_world_height','focus_distance'].includes(key)&&Number.isFinite(Number(result[key]))&&Math.abs(Number(result[key])-state[key])>1e-9);
            // A text field emits input again on blur after change has finished its Undo.
            if(!changed.length)return;
            const grouped=!!cameraEdit;if(!grouped)beginCameraEdit();if(!cameraEdit)return;
            const {sequenceId}=cameraEdit;
            for(const key of changed)state[key]=Number(result[key]);
            addOrUpdateCameraKeyframe(cameraId,frame,{sequence_id:sequenceId,state,channel:'lens',undo:false});syncActiveCameraPreviewFromTimeline();
            if(!grouped)cinematicCameraFormFinish(false);
        });
        cinematicCameraPanel.updateSlot();
        const nameRow=cinematicCameraPanel.form.form_data.camera_name.bar;
        const settings=cinematicCameraPanel.inside_vue?.$el?.querySelector('.lf-camera-settings');
        if(settings&&nameRow){nameRow.classList.add('lf-camera-name-row');nameRow.append(settings);}

        cinematicPathPointerDown=event=>{
            if(event.button!==0||activeRenderJob||!cinematicCameraPath?.visible||!cinematicCameraPath.keyPoints)return;
            const preview=window.Preview?.all?.find(item=>item.canvas===event.target);if(!preview)return;
            const rect=preview.canvas.getBoundingClientRect();let nearest=null,distance=64;
            for(const entry of cinematicCameraPath.keyPoints){const point=new THREE.Vector3().fromArray(entry.position).project(preview.camera);if(point.z>1||point.z< -1)continue;const dx=rect.left+(point.x+1)*rect.width/2-event.clientX,dy=rect.top+(1-point.y)*rect.height/2-event.clientY,d=dx*dx+dy*dy;if(d<distance){nearest=entry;distance=d;}}
            if(nearest){pauseCinematicPlayback();Timeline.setTime(nearest.time);Animator.preview();event.preventDefault();event.stopImmediatePropagation();}
        };
        window.document.addEventListener('pointerdown',cinematicPathPointerDown,true);
    }

    function getViewportCameraControl(key) {
        const element=getCameraElementById(cinematicCameraView?.cameraId)||getSelectedCameraElement();
        if(!element||activeRenderJob)return null;
        const doc=readDocumentView(),sequence=resolveCameraSequence(doc,element.cinematic_camera_id),camera=getCamera(doc,element.cinematic_camera_id,sequence);
        if(!camera||!sequence)return null;
        const projection=sampleCamera(camera,currentCinematicFrame(sequence)).projection;
        return cinematicCameraPanel?.form?.form_data?.[key==='lens'?(projection==='orthographic'?'ortho_world_height':'focal_length_mm'):key];
    }

    function toggleCinematicCameraMonitor() {
        cinematicCameraMonitorEnabled=!cinematicCameraMonitorEnabled;
        syncCinematicCameraMonitor();
        dispatchCinematicEvent('lightflow_cinematic_ui_changed',{});
    }

    function toggleCinematicCameraPath() {
        cinematicCameraPathVisible=!cinematicCameraPathVisible;
        syncCinematicCameraPath();
        dispatchCinematicEvent('lightflow_cinematic_ui_changed',{});
    }

    function sequenceLibraryMenuItems(shot) {
        return [{name:cinematicUI("edit_sequence"),icon:'tune',click:()=>{cinematicLibraryVue?.select(shot.id);openManagerDialog();}},
                        {name:cinematicUI("show_camera_track"),icon:'videocam',click:()=>{cinematicLibraryVue?.select(shot.id);showActiveCameraTimelineTrack({select:true});}},
                        '_',
                        {name:cinematicUI("duplicate_sequence"),icon:'content_copy',click:()=>{const source=getSequence(readDocument(),shot.id);const copy=createSequence({...deepClone(source),id:createId('sequence'),name:source.name+' · '+cinematicUI("copy")});cinematicLibraryVue?.select(copy.id);}},
                        '_',{name:cinematicUI("delete_sequence"),icon:'delete',condition:()=>readDocument().sequences.length>1,click:()=>Blockbench.showMessageBox({title:cinematicUI("delete_sequence"),message:shot.name,buttons:['dialog.confirm','dialog.cancel'],confirm:0,cancel:1},result=>{if(result===0){deleteSequence(shot.id);cinematicLibraryVue?.sync();}})}];
    }

    function openViewportSequenceMenu(event) {
        if(!getActiveProject()||Project.mode!=='animate'||activeRenderJob)return;
        const doc=readDocumentView(),active=getSequence(doc),anchor=event?.currentTarget||event;
        const select=id=>{
            if(cinematicFlySession)finishCinematicFly(false);
            cinematicLibraryVue?.select?.(id);
        };
        new Menu([
            ...doc.sequences.map(sequence=>({name:sequence.name,icon:sequence.id===active?.id?'radio_button_checked':'theaters',click:()=>select(sequence.id)})),
            '_',
            {name:cinematicUI("create_sequence"),icon:'add',click:()=>{if(cinematicFlySession)finishCinematicFly(false);cinematicLibraryVue?.create?.();}},
            {name:cinematicUI("add_animation_or_sequence"),icon:'playlist_add',click:()=>{setCinematicSequencePreview(true);sequenceAddClipMenu(0,anchor);}},
            {name:cinematicUI("sequence_actions"),icon:'more_horiz',condition:()=>!!active,children:()=>sequenceLibraryMenuItems(active)},
            '_',
            {name:cinematicUI("back_to_animation"),icon:'movie',condition:()=>cinematicSequencePreview,click:()=>setCinematicSequencePreview(false)}
        ]).open(anchor);
    }

    function openViewportCameraMenu(event) {
        if (!getActiveProject() || activeRenderJob) return;
        const doc = readDocumentView();
        const selected = getSelectedCameraElement();
        const showPanel = cameraId => {
            if(cinematicFlySession&&cinematicFlySession.cameraId!==cameraId)finishCinematicFly(false);
            selectCameraElement(cameraId);
            cinematicCameraPanel?.updateSlot();
            cinematicCameraPanel?.selectTab?.();
            if (cinematicCameraPanel?.folded) cinematicCameraPanel.fold(false);
            cinematicCameraPanel?.inside_vue?.sync?.();
        };
        new Menu([
            ...doc.cameras.map(camera => ({
                name: camera.name,
                icon: selected?.cinematic_camera_id === camera.id ? 'radio_button_checked' : 'videocam',
                click: () => showPanel(camera.id)
            })),
            ...(doc.cameras.length ? ['_'] : []),
            cameraAction,
            ...(selected ? [
                {name: cinematicUI("camera_panel"), icon: 'tune', click: () => showPanel(selected.cinematic_camera_id)},
                viewThroughCameraAction,
                updateCameraFromViewAction, keyframeAction,
                {name: cinematicUI("show_camera_keyframes"), icon: 'timeline', click: () => cinematicCameraPanel?.inside_vue?.keys?.()},
                {name: cinematicUI("camera_motion_path"), icon: cinematicCameraPathVisible ? 'check_box' : 'check_box_outline_blank', click: () => cinematicCameraPanel?.inside_vue?.trail?.()},
                '_', cameraSettingsAction
            ] : [])
        ]).open(event?.currentTarget || event);
    }

    function syncCinematicCameraPath() {
        const element=getSelectedCameraElement(),doc=readDocumentView(),camera=doc.cameras.find(item=>item.id===element?.cinematic_camera_id),sequence=resolveCameraSequence(doc,camera?.id);
        const visible=Project?.mode==='animate'&&!!camera&&!!sequence&&cinematicCameraPathVisible&&Canvas.show_gizmos!==false&&!activeRenderJob;
        if(cinematicCameraPath)cinematicCameraPath.visible=visible;
        if(!visible)return;
        const color=getComputedStyle(window.document.body).getPropertyValue('--lf-cinematic-camera').trim()||'#E8A8B5';
        const animation=window.Animation?.selected,animator=animation?.animators[element.uuid];
        const sources=cinematicSequencePreview?getCinematicAnimations():getCinematicAnimations().filter(item=>item.playing);
        const nodes=new Set();
        for(const candidate of cameraElementType.all){let node=candidate;while(node&&node!=='root'){if(node.mesh)nodes.add(node);node=node.parent;}}
        const signature=JSON.stringify([camera,sequence,cinematicSequencePreview,
            sources.map(item=>[item.uuid,item.playing,item.loop,item.blend_weight,item.override,Object.entries(item.animators).map(([id,value])=>[id,value.keyframes.map(key=>key.getUndoCopy())])]),
            [...nodes].filter(node=>node.type!=='lightflow_camera').map(node=>[node.uuid,node.origin,node.rotation]),color]);
        if(signature===cinematicCameraPathSignature&&cinematicCameraPath?.parent===Canvas.scene)return;
        cinematicCameraPathSignature=signature;
        if(!cinematicCameraPath){
            cinematicCameraPath=new THREE.Group();cinematicCameraPath.no_export=true;
            const line=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color,depthTest:true,depthWrite:false}));
            const keys=new THREE.Points(new THREE.BufferGeometry(),new THREE.PointsMaterial({color,size:8,sizeAttenuation:false,depthTest:true,depthWrite:false}));
            line.raycast=()=>{};keys.raycast=()=>{};line.no_export=keys.no_export=true;cinematicCameraPath.add(line,keys);
        }
        if(cinematicCameraPath.parent!==Canvas.scene){
            Canvas.scene.add(cinematicCameraPath);
            window.LightflowAmbientOcclusion?.invalidateSceneCache?.();
        }
        const positions=[],keyPositions=[],keyPoints=[],savedTime=Timeline.time,parserAnimation=Animator.MolangParser.context.animation,savedPlan=cinematicCompositionPlan;
        const snapshots=[...nodes].map(node=>({node,position:node.mesh.position.clone(),rotation:node.mesh.rotation.clone(),scale:node.mesh.scale.clone(),fixPosition:node.mesh.fix_position?.clone(),fixRotation:node.mesh.fix_rotation?.clone(),preRotation:node.mesh.pre_rotation?.clone()}));
        const variables=Animator.MolangParser.variables&&deepClone(Animator.MolangParser.variables);
        const pointAt=frame=>{
            const state=sampleCamera(camera,frame),time=frameToTimelineSeconds(sequence,frame,true);
            const plan=cinematicSequencePreview?buildSequenceComposition(sequence,frame,doc):null;
            cinematicCompositionPlan=plan;
            for(const saved of snapshots){const mesh=saved.node.mesh;mesh.position.copy(saved.fixPosition||saved.position);mesh.rotation.copy(saved.fixRotation||saved.rotation);mesh.scale.copy(saved.scale);}
            const prepared=new Set(),cameraStates=plan?.cameras||[{cameraId:camera.id,state}];
            for(const entry of cameraStates)if(!prepared.has(entry.cameraId)){
                prepared.add(entry.cameraId);const candidate=getCameraElementById(entry.cameraId);if(!candidate?.mesh)continue;
                const local=getLocalCameraTransform(candidate,entry.state),mesh=candidate.mesh;mesh.position.copy(local.position);mesh.quaternion.copy(local.quaternion);
                mesh.fix_position=mesh.position.clone();mesh.fix_rotation=mesh.rotation.clone();
            }
            const entries=plan?.animations||sources.map(item=>({animation:item,time,weight:1,loop:item.loop==='loop'}));
            for(const node of nodes){Animator.resetLastValues();for(const entry of entries){
                const sourceAnimator=entry.animation.animators[node.uuid];if(!sourceAnimator||entry.weight<=0)continue;
                Timeline.time=entry.time;Animator.MolangParser.context.animation=entry.animation;
                const loop=entry.animation.loop,override=entry.animation.override;
                try{entry.animation.loop=entry.loop?'loop':'hold';if(entry.weight<1)entry.animation.override=false;
                    const multiplier=entry.animation.blend_weight?Math.max(0,Animator.MolangParser.parse(entry.animation.blend_weight)):1;
                    sourceAnimator.displayFrame(entry.weight*multiplier);
                }finally{entry.animation.loop=loop;entry.animation.override=override;}
            }}
            return evaluatedCameraState(camera,sequence,frame).position;
        };
        try{
            const nativeFrames=animator?.position?.map(key=>timelineSecondsToFrame(sequence,key.time))||[];
            const first=cinematicSequencePreview?sequence.start_frame:Math.min(camera.keyframes[0]?.frame??sequence.start_frame,...nativeFrames),last=cinematicSequencePreview?sequence.end_frame-1:Math.max(sequence.end_frame-1,camera.keyframes.at(-1)?.frame??0,...nativeFrames,Math.round((animation?.length||0)*frameRateValue(sequence.frame_rate)));
            const steps=Math.min(128,Math.max(1,last-first));
            for(let index=0;index<=steps;index++)positions.push(...pointAt(first+(last-first)*index/steps));
            const frames=new Set(camera.keyframes.map(key=>key.frame));
            if(animator?.position?.length&&!cinematicSequencePreview)animator.position.forEach(key=>frames.add(timelineSecondsToFrame(sequence,key.time)));
            for(const frame of frames){const position=pointAt(frame);keyPositions.push(...position);keyPoints.push({position,time:frameToTimelineSeconds(sequence,frame,true)});}
        }finally{
            Timeline.time=savedTime;Animator.MolangParser.context.animation=parserAnimation;cinematicCompositionPlan=savedPlan;
            if(variables)Animator.MolangParser.variables=variables;
            for(const saved of snapshots){const mesh=saved.node.mesh;mesh.position.copy(saved.position);mesh.rotation.copy(saved.rotation);mesh.scale.copy(saved.scale);mesh.fix_position=saved.fixPosition;mesh.fix_rotation=saved.fixRotation;if(saved.preRotation)mesh.pre_rotation=saved.preRotation;}
            Canvas.scene.updateMatrixWorld();Animator.resetLastValues();
        }
        const [line,keys]=cinematicCameraPath.children;
        line.geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));line.geometry.computeBoundingSphere();
        keys.geometry.setAttribute('position',new THREE.Float32BufferAttribute(keyPositions,3));keys.geometry.computeBoundingSphere();
        line.material.color.set(color);keys.material.color.set(color);cinematicCameraPath.keyPoints=keyPoints;cinematicCameraPath.visible=visible;
    }

    function installCameraLensTool() {
        if(typeof Tool==='undefined'||typeof THREE==='undefined'||!window.document)return;
        const finish=cancel=>{
            const drag=cameraHandleDrag;if(!drag)return;cameraHandleDrag=null;
            try{drag.canvas?.releasePointerCapture?.(drag.id);}catch(_){}
            if(cancel)Undo.cancelEdit?.(true);else Undo.finishEdit(cinematicUI("adjust_camera_lens_focus"),{[CINEMATIC_UNDO_ASPECT]:true});
            syncCameraElementsFromDocument();Blockbench.setStatusBarText?.('');
        };
        cameraLensTool=new Tool('lightflow_cinematic_lens_tool',{
            name:cinematicUI("camera_lens_focus"),description:cinematicUI("drag_the_gold_diamond_for_framing_or_the_mint_cross_for_focus_sh"),
            icon:'camera',modes:['edit','animate','render'],selectElements:false,transformerMode:'hidden',
            condition:()=>!!getSelectedCameraElement()&&!activeRenderJob,
            onSelect:syncCameraGizmoVisibility,onUnselect(){finish(true);for(const element of cameraElementType?.all||[])if(element.mesh?.cinematicHandles)element.mesh.cinematicHandles.group.visible=false;}
        });
        window.LightManagerUI?.removeToolbarAction?.(cameraLensTool);
        cameraHandlePointerDown=event=>{
            if(event.button!==0||window.Toolbox?.selected!==cameraLensTool||activeRenderJob)return;
            const element=getSelectedCameraElement(),preview=window.Preview?.all?.find(view=>view.canvas===event.target);
            if(!element?.mesh?.visible||!preview)return;
            const rect=preview.canvas.getBoundingClientRect(),ray=new THREE.Raycaster();
            ray.setFromCamera(new THREE.Vector2((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1),preview.camera);
            const helpers=element.mesh.cinematicHandles;if(!helpers?.group.visible)return;
            const hit=ray.intersectObjects([helpers.focus,helpers.lens],false)[0];if(!hit)return;
            const doc=readDocument(),sequence=resolveCameraSequence(doc,element.cinematic_camera_id),camera=getCamera(doc,element.cinematic_camera_id,sequence);if(!sequence||!camera)return;
            const frame=clamp(timelineSecondsToFrame(sequence,window.Timeline?.time||0),sequence.start_frame,sequence.end_frame-1);
            pauseCinematicPlayback();Undo.initEdit({[CINEMATIC_UNDO_ASPECT]:true});
            cameraHandleDrag={id:event.pointerId,x:event.clientX,y:event.clientY,amount:0,canvas:preview.canvas,kind:hit.object.userData.cinematicHandle,state:sampleCamera(camera,frame)||camera.base,cameraId:camera.id,sequenceId:sequence.id,frame};
            try{preview.canvas.setPointerCapture?.(event.pointerId);}catch(_){}
            event.preventDefault();event.stopImmediatePropagation();
        };
        cameraHandlePointerMove=event=>{
            const drag=cameraHandleDrag;if(!drag||event.pointerId!==drag.id)return;
            const scale=event.shiftKey?.1:1,state={...drag.state};
            drag.amount+=(drag.kind==='lens'?event.clientX-drag.x:drag.y-event.clientY)*.007*scale;
            drag.x=event.clientX;drag.y=event.clientY;
            if(drag.kind==='lens'){
                if(state.projection==='orthographic'){
                    state.ortho_world_height=clamp(state.ortho_world_height*Math.exp(drag.amount),.001,100000);
                    drag.amount=Math.log(state.ortho_world_height/drag.state.ortho_world_height);
                }else{
                    state.focal_length_mm=clamp(state.focal_length_mm*Math.exp(-drag.amount),.1,2000);
                    drag.amount=-Math.log(state.focal_length_mm/drag.state.focal_length_mm);
                }
            }else{
                state.focus_distance=clamp(state.focus_distance*Math.exp(drag.amount),.0001,100000);
                drag.amount=Math.log(state.focus_distance/drag.state.focus_distance);
            }
            addOrUpdateCameraKeyframe(drag.cameraId,drag.frame,{sequence_id:drag.sequenceId,state,undo:false});
            syncCameraElementsFromDocument();
            Blockbench.setStatusBarText?.(drag.kind==='lens'?cinematicUI("lens")+': '+(state.projection==='orthographic'?state.ortho_world_height.toFixed(2):state.focal_length_mm.toFixed(1)+' mm'):cinematicUI("focus")+': '+state.focus_distance.toFixed(2));
            event.preventDefault();event.stopImmediatePropagation();
        };
        cameraHandlePointerUp=event=>{if(event.type==='keydown'){if(event.key==='Escape')finish(true);return;}if(cameraHandleDrag&&event.pointerId===cameraHandleDrag.id){finish(event.type==='pointercancel');event.stopImmediatePropagation();}};
        cameraHandleWindowBlur=()=>finish(true);
        window.addEventListener('blur',cameraHandleWindowBlur);
        window.document.addEventListener('pointerdown',cameraHandlePointerDown,true);window.document.addEventListener('pointermove',cameraHandlePointerMove,true);
        for(const event of ['pointerup','pointercancel','keydown'])window.document.addEventListener(event,cameraHandlePointerUp,true);
        cinematicSelectionListener=Blockbench.on('update_selection',syncCameraGizmoVisibility);
    }

    function installCameraTransforms() {
        const nativeEdit=window.TransformerModule?.modules?.edit;
        if(!nativeEdit)return;
        const selectedCameras=()=>{
            const nodes=window.Outliner?.selected||[];
            return nodes.length&&nodes.every(node=>node.type==='lightflow_camera')?nodes:[];
        };
        cameraNativeTools=['move_tool','rotate_tool'].map(id=>{
            const tool=BarItems[id];if(!tool)return null;
            const previousCondition=tool.condition,previousModes=tool.modes;
            const modes=Array.from(new Set([...(previousModes||[]),'render']));
            const condition=()=>selectedCameras().length?!activeRenderJob:Condition(previousCondition);
            tool.modes=modes;tool.condition=condition;
            return {delete(){if(tool.modes===modes)tool.modes=previousModes;if(tool.condition===condition)tool.condition=previousCondition;}};
        }).filter(Boolean);
        cameraTransformModule=new TransformerModule('lightflow_cinematic_camera',{
            priority:3,
            condition:()=>!activeRenderJob&&selectedCameras().length>0&&!(window.Modes?.animate&&window.Animation?.selected&&!cinematicSequencePreview)&&['move_tool','rotate_tool'].includes(Toolbox.selected.id)&&['edit','animate','render'].includes(Project.mode),
            updateGizmo(){
                const node=selectedCameras().find(camera=>camera.visibility!==false);if(!node)return false;
                Transformer.rotation_object=node;
                if(Toolbox.selected.id==='rotate_tool')node.mesh.getWorldPosition(Transformer.position).sub(scene.position);
                else Transformer.position.fromArray(getSelectionCenter());
                const space=getEditTransformSpace();
                if(space>=2)Transformer.rotation_ref=node.mesh;
                else if(space instanceof OutlinerNode&&space.getTypeBehavior('parent'))Transformer.rotation_ref=space.mesh;
                return true;
            },
            calculateOffset:nativeEdit.calculateOffset,
            onStart(context){
                if(cinematicFlySession)finishCinematicFly(false);
                pauseCinematicPlayback();this.cameraRotationFrame=null;
                // Begin relative native dragging at the visible timeline pose.
                for(const element of selectedCameras()){
                    const doc=readDocumentView(),sequence=resolveCameraSequence(doc,element.cinematic_camera_id),camera=getCamera(doc,element.cinematic_camera_id,sequence);
                    if(camera&&sequence)applyCameraTimelineStateToElement(element,cameraElementWorldState(element,sampleCamera(camera,currentCinematicFrame(sequence))),sequence);
                }
                nativeEdit.onStart.call(this,context);
            },
            onMove(context){
                if(Toolbox.selected.id!=='rotate_tool')return nativeEdit.onMove.call(this,context);
                const difference=context.value-(this.initial_value||0),space=getEditTransformSpace();
                this.cameraRotationFrame||=new Map();
                for(const node of selectedCameras()){
                    node.mesh.updateWorldMatrix(true,false);
                    if(!this.cameraRotationFrame.has(node))this.cameraRotationFrame.set(node,{rotation:node.rotation.slice(),quaternion:node.mesh.quaternion.clone(),parent:node.mesh.parent.getWorldQuaternion(new THREE.Quaternion())});
                    const initial=this.cameraRotationFrame.get(node);
                    const axis=context.axis_number===undefined?context.rotate_normal:context.axis_number;
                    const normal=axis instanceof THREE.Vector3?axis.clone():new THREE.Vector3().setComponent(axis,1);
                    const radians=THREE.MathUtils.degToRad(difference);
                    let target;
                    if(space>=2)target=initial.quaternion.clone().multiply(new THREE.Quaternion().setFromAxisAngle(normal,radians));
                    else{
                        if(space===0)normal.applyQuaternion(initial.parent.clone().invert());
                        else if(space instanceof OutlinerNode)normal.applyQuaternion(space.mesh.getWorldQuaternion(new THREE.Quaternion())).applyQuaternion(initial.parent.clone().invert());
                        target=new THREE.Quaternion().setFromAxisAngle(normal,radians).multiply(initial.quaternion);
                    }
                    const euler=new THREE.Euler().setFromQuaternion(target,node.mesh.rotation.order);
                    setArrayProperty(node,'rotation',difference===0?initial.rotation:[euler.x,euler.y,euler.z].map(THREE.MathUtils.radToDeg));
                    node.preview_controller.updateTransform(node);
                }
                Transformer.updateSelection();
            },
            onEnd(context){nativeEdit.onEnd.call(this,context);this.cameraRotationFrame=null;},
            onCancel(context){nativeEdit.onCancel.call(this,context);this.cameraRotationFrame=null;}
        });
    }

