        if(fly.animation)Animator.preview();
        else if(camera&&sequence)applyCameraStateToElement(getCameraElementById(camera.id),sampleCamera(camera,fly.frame),{sequence});
        preview.setProjectionMode(fly.before.ortho);preview.camPers.copy(fly.before.perspective);preview.camOrtho.copy(fly.before.orthographic);
        preview.controls.target.copy(fly.before.target);preview.controls.enabled=fly.before.enabled;preview.controls.unlinked=fly.before.unlinked;
        if(fly.before.tabindex===null)preview.canvas.removeAttribute('tabindex');else preview.canvas.setAttribute('tabindex',fly.before.tabindex);
        if(fly.before.lookThrough){
            if(!cancel)applyPhysicalStateFallback(fly.state,preview);
            setCinematicCameraView({preview,cameraId:fly.cameraId,position:preview.camera.position.clone(),quaternion:preview.camera.quaternion.clone()});
        }
